quests[39946] = { id = 39946, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das richtige Werkzeug zur Hand", description = "Durch das Wenige, das ich entschlüsseln konnte, weiß ich, dass die Tafeln mit einem speziellen Werkzeug bearbeitet werden.\n\nWenn wir eins dieser Werkzeuge und einen kompletten Kodex hätten, könnten wir mit Leichtigkeit unsere eigene Schrifttafel herstellen.\n\nDas würde außerdem beweisen, dass ich ihre Sprache erfolgreich entschlüsselt habe.\n\nBringt mir eins dieser Werkzeuge, {name}.", sourceObjective = "Holt ein runenverziertes Knochenmesser.", progress = "Das Messer ist der letzte Schlüssel zu meinen Forschungen. Habt Ihr schon eins gefunden?", completion = "Mann... Das ist... viel größer, als ich erwartet habe.\n\nAndererseits, Vrykul sind sehr groß und ich... nun ja, ich nicht.\n\nDennoch glaube ich, dass ich damit arbeiten kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[39947] = { id = 39947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht so kompliziert?", description = "Also schön, ich glaube, ich habe jetzt alle fehlenden Eintragungen in den Kodex nachgetragen. Und wir haben die Machete... äh... das Messer.\n\nJetzt müssen wir nur noch unsere eigene Tafel machen und meinen anderen Verdacht über die Tafeln bestätigen.\n\nIch glaube nämlich, dass es sich nicht nur um einfache Texte handelt, sondern um eine Art magisches Gerät.", sourceObjective = "Helft Nicholo bei der Erstellung der Runentafel.", completion = "Wie gut, dass Ihr hier wart, um mir dabei zu helfen.\n\nDiese Geister hätten mich mit Sicherheit getötet!", sourceObjectiveStatus = "unverified-source-field" }
quests[39948] = { id = 39948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tintenfluss", description = "{name}, Ihr müsst für mich schnell etwas abliefern.\n\nJa, ich habe inzwischen herausgefunden, dass so einfache Aufgaben unter Eurer Würde sind, aber ich bin gerade sehr beschäftigt und wir beide wissen, dass meine Zeit viel wichtiger ist als Eure.\n\nBringt diese Mordaufträge zu Raethan, dem Wachhauptmann in Dalarans Schattenseite.", sourceObjective = "Bringt die Mordaufträge zu Raethan in der Schattenseite.", completion = "Sie scheinen alle in Ordnung zu sein.\n\nWenn Ihr also einen Moment Zeit habt, Schreiber, hätte ich ein Angebot für Euch, das Euch interessieren dürfte...", sourceObjectiveStatus = "unverified-source-field" }
quests[39949] = { id = 39949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frühere Schreiberkollegen", description = "Die Kanalisation ist so etwas wie ein... \"Rückzugsort\" für jene, die den Anforderungen des normalen Lebens in Dalaran nicht gewachsen sind. Das Ziel dieses Auftrags ist ein gutes Beispiel dafür.\n\nSein Name ist Modertint. Er war einst ein Schreiber wie Ihr, aber die Belastung im Umgang mit dem Professor hat ihn in den Wahnsinn getrieben.\n\n<Raethan übergibt Euch den Mordauftrag.>\n\nHier steht, dass er Cartier und Co. einen Edelstein gestohlen hat. Bringt mir diesen Edelstein. Was immer er sonst noch bei sich hat, könnt Ihr behalten.", sourceObjective = "Tötet Modertint und nehmt ihm den gestohlenen Schattenrubin ab.", progress = "Hat er viel Gegenwehr geleistet?", completion = "Ihr, {name}, seid ein Geschenk des Himmels. Ich dachte, ich würde diese Nervensäge nie loswerden.\n\nWie versprochen ist hier das Kopfgeld für den Auftrag.", sourceObjectiveStatus = "unverified-source-field" }
quests[39950] = { id = 39950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein merkwürdiges Schmuckstück", description = "Moment noch, {name}... Habt Ihr das hier bemerkt?\n\n<Raethan zieht ein kleines Stück Papier von der Unterseite des Edelsteins ab.>\n\nDas hier wurde nicht als gestohlen gemeldet. Es scheint eine Art Karte zu sein. Ist wohl so ein Schreiberding.\n\nVielleicht könnt Ihr ja etwas damit anfangen.", sourceObjective = "Gebt die modrige TarotkarteProfessor Pallin.", progress = "Was habt Ihr denn da?", completion = "Ich... Ich kenne diese Arbeit. Mein früherer Lehrling, wie hieß er noch gleich, hat versucht, zu beweisen, dass er genau wie ich etwas Großartiges erschaffen kann.\n\nBeeindruckenderweise ist es ihm in diesem Fall wohl gelungen.\n\nWir sollten aus dem, was er geschaffen hat, etwas lernen und unsere eigene, weniger grässliche Version herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39951] = { id = 39951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rosenrote Essenz", description = "<Das aus dieser Blume gewonnene Pigment ist von außergewöhnlich hoher Qualität.>\n\n<Professor Pallin hätte sicherlich Interesse daran.>", sourceObjective = "Bringt die rosenrote Essenz zu Professor Pallin in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Wie konntet Ihr ein so reines Extrakt herstellen? Zeigt mir bitte Schritt für Schritt, wie Ihr das gemacht habt.\n\nFaszinierend. Erlaubt Ihr mir, das aufzuschreiben und meinen anderen Schülern zu zeigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39952] = { id = 39952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fahle Essenz", description = "<Die Teufelswurz wurde zu einem dicken geronnenen Pigment eingedickt. Zwar sind alle Pigmente auf Basis von Teufelswurz eher aggressiv, aber diese Probe leuchtet geradezu vor böser Energie.>\n\n<Professor Pallin hätte sicherlich Interesse daran.>", sourceObjective = "Bringt die fahle Essenz zu Professor Pallin in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Wir befinden uns hier auf unbekanntem Forschungsgebiet, {name}. Tatsächlich kenne ich niemanden in meinem akademischen Umfeld, der Teufelswurz so effektiv verarbeiten kann.\n\nGut gemacht, Schüler. Oder sollte ich Euch fortan stellvertretender Juniorschreiberassistent nennen?\n\nAch, nein, Schüler gefällt mir immer noch besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[39953] = { id = 39953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Visionen von Tapferkeit", description = "Ich denke, es ist an der Zeit für einen weiteren Ausflug, {name}. Zu den Hallen der Tapferkeit!\n\nDie Valarjar sind Meister in allen möglichen Arten der Runenbearbeitung. Vielleicht finden wir dort etwas Nützliches für ein neues Rezept.", sourceObjective = "Holt 5 Runensiegel der Valarjar aus den Hallen der Tapferkeit.", progress = "Habt Ihr Götter gesehen, als Ihr dort wart?", completion = "Bei den Sternen... Die sind wirklich sehr hübsch! Tatsächlich kommt mir da eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[39954] = { id = 39954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Techniken der Massenmahlung", description = "Einige meiner vorherigen Schüler haben ihre Abneigung gegen das Mahlen zum Ausdruck gebracht. Sie fanden die Tätigkeit \"ermüdend\", \"nervraubend\" und sogar \"quälend\". Haben die denn gar keinen Respekt vor den traditionellen Arbeitsweisen der Inschriftenkunde?\n\nUnd ich wette, Ihr seid auch dieser Meinung, nicht wahr? Also gut, Ihr wart bis jetzt <ein guter Schüler/eine gute Schülerin>, also ist es einen Versuch wert.\n\nIch habe hier im Laden irgendwo ein Buch über die Techniken der Massenmahlung. Wenn Ihr es findet, gehört es Euch.", sourceObjective = "Sucht nach dem Handbuch des meisterhaften Mahlens im Inschriftenkundeladen in Dalaran.", progress = "Versucht, es so sauber wie möglich hinzubekommen.", completion = "Genau das! Hm... Mal sehen...\n\n<Pallin blättert flüchtig durch die Seiten des alten Buchs.>\n\nHier drin steht nicht viel, was Euch bei den Kräutern der Verheerten Inseln weiterhelfen könnte.\n\nAber Moment... Hier ist etwas...", sourceObjectiveStatus = "unverified-source-field" }
quests[39955] = { id = 39955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflisches Komplott", description = "Ja, ich streite es gar nicht ab. Der schlüpfrige Romantikschmöker gehört mir.\n\nAber ich kann Euch versichern, dass ich ihn nur wegen der schönen Handschrift lese! Der Autor schreibt so runde \"B\"s und so wohlgeformte \"D\"s!\n\nAlso, vielleicht solltet Ihr auch mal Nachhilfe in der Schreibkunst nehmen. Der Autor dieses Buchs heißt B. Speerfuchtel. Ihr müsstet ihn in der Bibliothek von Eisenschmiede antreffen.\n\nUnd jetzt hört auf, darin zu lesen, <Schüler/Schülerin>! Ihr könnt gehen. Und gebt mir mein Buch zurück.", sourceObjective = "Geht nach Eisenschmiede und sucht B. Speerfuchtel.", completion = "Hallo! Ihr müsst einer meiner vielen Fans sein, der ein Autogramm haben möchte.\n\nOh, Ihr seid hier wegen der Romantikschmöker? Wie ich sehe, habt Ihr mein kleines Geheimnis aufgedeckt.\n\nWisst Ihr, ich habe keine Lust mehr, sie zu schreiben. Ich habe mich weiterentwickelt, wisst Ihr? Ich habe den letzten gestern geschrieben,.\n\nVielleicht habt Ihr Lust, die Tradition weiterzuführen?", sourceObjectiveStatus = "unverified-source-field" }
quests[39956] = { id = 39956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das weitergegebene Vermächtnis", description = "Mir ist die Leidenschaft abhandengekommen, <Schreiber/Schreiberin>. Ich bin nicht mehr in der Lage, mich in die Charaktere hineinzuversetzen.\n\nSeht mal dieses unvollendete Buch da auf dem Tisch. Ich werde es wohl nicht mehr zu Ende bringen. Vielleicht wollt Ihr es mal versuchen.", sourceObjective = "Schreibt den unfertigen schlüpfrigen Romantikschmöker zu Ende.", completion = "Hm... Ja, Ihr scheint den Dreh raus zu haben. Diese Stelle hier gefällt mir besonders: \"Oh, Graf Grabesbann!\" Das wäre eine gute Einleitung...\n\nHier ist eine Liste mit noch mehr Ideen für Geschichten. Ich benötige sie nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[39957] = { id = 39957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonentinte", description = "Aus diesen Siegeln könnte man fantastische, neue Tarotkarten anfertigen und mit beträchtlicher Macht versehen. Wir benötigen dafür allerdings eine besonders robuste Tinte.\n\nAber zum Glück gibt es ja Schüler wie Euch, die selbst besonders schwierig zu besorgende Dinge herbeischaffen können.\n\nFür dieses Projekt benötige ich aus Dämonenblut gewonnene Tinte. Das Blut der Dämonen in der Teufelsseelenbastion sollte eine gute Basis ergeben. Aber Ihr benötigt natürlich auch noch das Blut von Sargeras.", sourceObjective = "Sammelt 25 Phiolen mit Teufelsseelenblut und 1 Probe des Bluts von Sargeras und mischt daraus Teufelsseelentinte.", progress = "Wenn Ihr nicht sicher seid, wo Ihr Dämonenblut findet, begebt Euch nach Suramar und seht Euch um. Dort werdet Ihr früher oder später über einen Dämon stolpern.", completion = "Das ist mehr als genug. Ausgezeichnete Arbeit!\n\n<Professor Pallin nimmt eine kleine Schreibfeder, taucht sie in die Tinte und beginnt, etwas auf eine kleine Karte zu schreiben.>\n\nWie ich dachte, einfach herzustellen.\n\nWie immer bei diesen Tarotkarten muss man aber ein vollständiges Set herstellen, damit sie ihr volles Potenzial entfalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[39958] = { id = 39958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harthäutig", description = "Ich heiße Euch willkommen, {name}. Es ist mir eine Ehre, mit jemandem Eures Ranges zusammenzuarbeiten.\n\nUm beginnen zu können, müssen wir aber zunächst ein paar Materialien sammeln.\n\nAuf den Verheerten Inseln gibt es viele seltsame, exotische Tiere, mit deren Bälgen man zweifelsohne ein paar schöne Experimente durchführen kann. Und wir benötigen auch Schuppen für Kettenrüstungen.\n\nZieht bitte los und holt uns ein paar Materialien, damit wir anfangen können.", sourceObjective = "Sammelt 20 Stücke Steinbalgleder und 5 Sturmschuppen. Wenn Ihr <kein Kürschner/keine Kürschnerin> seid, könnt Ihr diese Dinge im Auktionshaus oder von anderen Spielercharakteren erwerben.", progress = "Ich gehe davon aus, dass Ihr den Tieren einen gnadenvollen Tod gewährt habt?", completion = "Ich bin ja so neugierig auf diese Materialien. Ich kann es kaum erwarten, damit zu experimentieren!\n\nIch werde nur ein paar für meine Untersuchungen brauchen. Den Rest könnt Ihr wiederhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[39959] = { id = 39959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflisches Komplott", description = "Ja, ich streite es gar nicht ab. Der schlüpfrige Romantikschmöker gehört mir.\n\nAber ich kann Euch versichern, dass ich ihn nur wegen der schönen Handschrift lese! Der Autor schreibt so runde \"B\"s und so wohlgeformte \"D\"s!\n\nAlso, vielleicht solltet Ihr auch mal Nachhilfe in der Schreibkunst nehmen. Der Autor dieses Buchs heißt B. Bricht. Ihr müsstet ihn in der Bibliothek von Unterstadt antreffen.\n\nUnd jetzt hört auf, darin zu lesen, <Schüler/Schülerin>! Ihr könnt gehen. Und gebt mir mein Buch zurück.", sourceObjective = "Begebt Euch nach Unterstadt und sucht nach B. Bricht.", completion = "Wollt Ihr ein Autogramm? Also gut, Ihr dürft mir Eure Brust darbieten.\n\nOh, Ihr seid hier wegen der Romantikschmöker? Ich sehe, Ihr habt mein kleines Geheimnis aufgedeckt.\n\nWisst Ihr, ich habe keine Lust mehr, sie zu schreiben. Ich habe mich anderen Dingen zugewandt, versteht Ihr? Ich habe gestern den letzten geschrieben.\n\nDoch vielleicht möchtet Ihr die Tradition weiterführen...?", sourceObjectiveStatus = "unverified-source-field" }
quests[39960] = { id = 39960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das weitergegebene Vermächtnis", description = "Mir ist die Leidenschaft abhandengekommen, <Schreiber/Schreiberin>. Ich bin nicht mehr in der Lage, mich in die Charaktere hineinzuversetzen.\n\nSeht mal dieses unvollendete Buch da auf dem Tisch. Ich werde es wohl nicht mehr zu Ende bringen. Vielleicht wollt Ihr es mal versuchen.", sourceObjective = "Schreibt den unfertigen schlüpfrigen Romantikschmöker zu Ende.", completion = "Hm... Ja, Ihr scheint den Dreh raus zu haben. Diese Stelle hier gefällt mir besonders: \"Oh, Graf Grabesbann!\" Das wäre eine gute Einleitung...\n\nHier ist eine Liste mit noch mehr Ideen für Geschichten. Ich benötige sie nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[39961] = { id = 39961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peinliche Offenbarung", description = "Das scheint gar kein Fachbuch der Inschriftenkunde zu sein, sondern... ein schlüpfriger Romantikschmöker! Auf allen Seiten finden sich unzählige, geschmacklose Szenen der Fleischeslust.\n\nOb es trotzdem der Inschriftenkunde dient? Auf jeden Fall sollte Professor Pallin zur Rede gestellt werden.", sourceObjective = "Bringt den schlüpfrigen Romantikschmöker zu Professor Pallin.", completion = "Hände weg von... äh, ich meine... das gehört nicht mir...\n\nWo habt Ihr denn...\n\n<Der Professor gerät ins Plappern.>\n\nIrgendjemand will mir wohl einen Streich spielen!", sourceObjectiveStatus = "unverified-source-field" }
quests[39962] = { id = 39962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Okuna in Schwierigkeiten", description = "<Ihr öffnet die Flasche und entdeckt darin eine Nachricht.>\n\nHilfe! Ich brauche Hilfe... aber nicht von irgendwem. Von einem Champion! Endlich konnte ich mich aus den Klauen von Prinz Ozeanus winden, da begann sein Vater König Klafterbart, Jagd auf mich zu machen.\n\nIch genoss meine Freiheit und wollte ein wenig angeln, da wurde ich von diesem Riesen angegriffen. Seitdem renne ich auf den Inseln herum und versuche, dieser Kreatur zu entgehen... Wenn jemand diese Nachricht findet, schickt bitte Hilfe!", sourceObjective = "Sucht nach Okuna Langhauer.", sourceObjectiveStatus = "unverified-source-field" }
quests[39963] = { id = 39963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Fishing Pole" }
quests[39969] = { id = 39969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod für Azshara" }
