quests[39982] = { id = 39982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koltira Deathweaver Slotted" }
quests[39983] = { id = 39983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Krieg - Die Ankunft", description = "Die Stärke unseres Stammes lässt sich auf Huln Hochberg zurückführen. Als die Legion uns das letzte Mal auslöschen wollte, hat er sie besiegt und viele der verstreuten, kleineren Stämme vereint.\n\nDurchlebt seine Geschichte, um zu verstehen, warum sein Name den Ängstlichen Mut macht und den Mutigen Angst einflößt.", sourceObjective = "Besiegt 25 Kämpfer der Legion.", completion = "[In gebrochener Gemeinsprache] Gefiederter sagte, Ihr kommt. Unng Ak keine Hoffnung, Ihr kommt. Danke Tauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[39984] = { id = 39984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relikte der Vergangenheit", description = "<Der Tagebucheintrag scheint in Eile geschrieben worden zu sein.>\n\nIch weiß nicht, was aus meinem Dorf geworden ist. Seit sich die Nebel über den Hafen gelegt haben, sind die Bewohner ganz anders.\n\nEinige sind aggressiv und gewalttätig, andere scheinen schlicht verrückt geworden zu sein. Viele sind raus in den Nebel gelaufen und nicht wieder zurückgekehrt.\n\nNormalerweise können wir uns in solchen Zeiten auf unseren Anführer, Jarl Tarben, verlassen. Aber leider ist auch er vom Nebel verschluckt worden.\n\nIch weiß nicht, was jetzt aus mir wird. Vorerst kann ich nur auf meinem Posten bleiben und auf der Hut sein.", sourceObjective = "Sucht nach Hinweisen, die Auskunft über das Schicksal des Wellenskornhafens geben.", completion = "Die Nebel dieser Bucht lassen nicht nur das Holz der Schiffe verrotten, sondern auch die Seelen ihrer Bewohner.\n\nAber wie es scheint, habt Ihr das bereits entdeckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39985] = { id = 39985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgars Entdeckung", description = "Champion! Bitte kommt unverzüglich zur Violetten Zitadelle.\n\nIch habe eine Entdeckung gemacht, die ich Euch und dem Rat der Sechs vorstellen möchte.", sourceObjective = "Sprecht mit Erzmagier Khadgar in Dalaran.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[39986] = { id = 39986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Mitteilung", description = "Die letzten 10.000 Jahre lang war die Elfenstadt Suramar durch eine Arkanbarriere abgeriegelt, wie einst auch Dalaran.\n\nDiese Barriere hat sich aufgelöst.\n\nSeither gehen Wellen magischer Energie von der Stadt aus, wie von einem Stein, der in einen Teich fällt. In diesen Wellen habe ich ein Muster wahrgenommen.\n\nEin verschlüsselter Zauber, der sich im Chaos verbirgt.\n\nIch habe den Zauber hier kopiert. Er ist nicht gefährlich, aber darüber hinaus habe ich keine Ahnung, wozu er dient!", sourceObjective = "Untersucht die Arkananomalie in Dalaran.", progress = "Seht es Euch ruhig an.", completion = "Eine Art magische Flaschenpost, unter den Augen der Legion hindurchgeschmuggelt... Clever.", sourceObjectiveStatus = "unverified-source-field" }
quests[39987] = { id = 39987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spur der Echos", description = "Die Nachtgeborenen könnten sich noch als mächtige Verbündete gegen die Legion erweisen. Wir müssen dieser Thalyssra helfen, so gut es geht.\n\nWir können sie finden, indem wir ihre magischen Echos zurückverfolgen, genau so, wie ich auch ihren Hilferuf gefunden habe.\n\nIch kann Euch in die Nähe der Stelle teleportieren, an der sie die Nachricht aufgezeichnet hat. Von dort aus müsst Ihr nach Wellen im Gefüge des Arkanen selbst suchen.\n\nMit meinem Zauberstab sollte das gehen. Folgt dessen Funken. Sie sollten Euch dorthin geleiten, wo Thalyssra ihre Magie genutzt hat.", sourceObjective = "Verwendet Khadgars Zauberstab, um Arkanechos aufzuspüren und die Erste Arkanistin Thalyssra zu finden.", progress = "Wer seid Ihr?", completion = "Ein Fremder...\n\nHabt Ihr meine Nachricht erhalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[39988] = { id = 39988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Krieg - Sturmgrimm", description = "<Eche'ro stupst Eure Hand an und dreht sich um. Dabei wirft er einen Blick zurück und bedeutet Euch, nach Süden zu gehen.>", sourceObjective = "Trefft Euch mit Malfurion.", completion = "Ihr bringt Eche'ro mit Euch und... Was ist das? Der Segen des Cenarius?!", sourceObjectiveStatus = "unverified-source-field" }
quests[39990] = { id = 39990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Krieg - Verstärkungen", description = "Cenarius hat viel riskiert, indem er hierhergekommen ist – wenn auch nur kurz –, um Euch einen Segen zu gewähren. Er hat gesehen, was Ihr zu leisten imstande seid, und hat Euch zum Champion in seinem Kampf erwählt. Ich werde später mit Euch darüber sprechen. Das ist wirklich ein seltenes Geschenk.\n\nAber jetzt bitte ich um Eure Hilfe, Huln Hochberg. Ich muss meine Beschwörungen abschließen, damit Dryaden, die sich jenseits des Schleiers befinden, Zugang zu diesem Ort finden und uns helfen können.", sourceObjective = "Beschützt Malfurion.", progress = "Es sollte nicht lange dauern. Bitte erlaubt ihnen nicht, meinen Zauber zu unterbrechen.", completion = "Das Ritual ist vollendet. Verstärkung wird durch das Portal kommen und uns im Kampf gegen die dämonische Horde unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[39991] = { id = 39991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blessing of Cenarius" }
quests[39992] = { id = 39992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Krieg - Die Nathrezim", description = "Ich bin vollauf damit beschäftigt, meine Truppen und die Planung für den bevorstehenden Kampf zu organisieren.\n\nIch würde den Schreckenslord Tichondrius ja gerne persönlich töten, aber ich überlasse Euch diese Ehre, Huln Hochberg.", sourceObjective = "Besiegt Tichondrius.", completion = "Versteht Ihr jetzt, wie mächtig Huln war? Er hat die Stämme vereint und unfassbar mächtige Feinde besiegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[39993] = { id = 39993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abandoned Fishing Pole" }
quests[39994] = { id = 39994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crab Rider Grmlrml" }
quests[39998] = { id = 39998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibt die Wellenskorn zurück" }
quests[40000] = { id = 40000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahre Jäger", description = "Ich weiß nicht, warum Hemet mit Razik auf die Jagd geht. Seine Gerätschaften sind im besten Falle unzuverlässig!\n\nWahre Jäger brauchen keine solchen Spielereien für die Jagd. Sie verlassen sich auf Instinkt, Fertigkeiten und Agilität.\n\nSagt, {name}, habt Ihr die Fähigkeiten eines wahren Jägers? Dann beweist es.\n\nErlegt ein paar Knochenschnabelfalken, die im nahegelegenen Becken ihre Kreise ziehen.", sourceObjective = "Stellt Euer Jägertalent unter Beweis, indem Ihr Knochenschnabelfalken auf der Sonnenfrostlichtung erlegt.", progress = "Wenn wir hier quatschen, könnt Ihr ja keine Falken jagen.", completion = "So machen das die wahren Jäger.", sourceObjectiveStatus = "unverified-source-field" }
quests[40001] = { id = 40001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vor der Pforte der Tapferkeit", description = "Zwar ist es Euch vorbestimmt, die Hallen der Tapferkeit zu erobern, aber der Gottkönig mit seinen Dämonen und seiner Verschlagenheit schändet die heiligen Treppen und macht Euch diesen Anspruch streitig.\n\nEure Drachenverbündeten sind zur Verteidigung der Hallen geeilt, aber sie benötigen Eure Unterstützung. Die Vrykul haben den Anführer der Sturmdrachen gefangen genommen, der Euch als Vethir bekannt ist.\n\nBefreit Euren Drachenfreund, Champion, und fegt die Teufelsskorn von der Pforte der Tapferkeit!", sourceObjective = "Findet Vethir im Lager der Teufelsskorn.", completion = "Aber das ist ja...?\n\nDas Gesicht eines Freundes in einem Meer von Feinden?", sourceObjectiveStatus = "unverified-source-field" }
quests[40002] = { id = 40002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein vertrautes Schicksal", description = "Wir sind hierhergekommen, um die Hallen der Tapferkeit zu verteidigen... Sie haben mich vom Himmel geholt...\n\nIch kann aus diesen Fesseln nicht ausbrechen. Findet den Kerkermeister, der diese Zelle eingerichtet hat...\n\nBitte befreit mich, <mein Freund/meine Freundin>...", sourceObjective = "Nehmt Dravax den Splitter des Kerkermeisters ab und befreit Vethir aus seinem Gefängnis.", progress = "Der Kerkermeister hat... den Schlüssel...", completion = "Ihr versteht es immer noch, mich zu überraschen, Fremder. Eure Prüfungen sind vorüber und dennoch müsst Ihr weitere Herausforderungen meistern.\n\nDie Truppen des Gottkönigs sind zahlreich, aber die Waffe in Eurem Besitz birgt die gesamte Macht Sturmheims in sich! Wenn Ihr Euch den Toren nähert, wird diese Macht die Feinde des Landes in die Knie zwingen!\n\nUnd jetzt lasst uns den Gottkönig angreifen und die Pforte der Tapferkeit von seiner verderbten Aura befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[40003] = { id = 40003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eindämmen der Flut", description = "Skovald und seine dämonischen Verbündeten haben die Pforte der Tapferkeit geschändet. Und seine verderbten Mystiker haben Portale errichtet, um seinen teuflischen Verbündeten aus verseuchten Welten Zutritt zu verschaffen.\n\nWenn wir die Flut dieser Feinde eindämmen wollen, müssen diese Portale verschlossen werden.\n\nIch werde meine Verbündeten zusammenrufen. Nehmt dieses Horn und blast Alarm, wenn Ihr ein Portal gefunden habt. Dann werden wir aus der Luft zuschlagen!", sourceObjective = "Verwendet das sturmgeschmiedete Horn, um drei Dämonenportale bei der Pforte der Tapferkeit zu vernichten.", progress = "Die Portale müssen geschlossen werden, wenn wir Skovalds Truppen aufhalten wollen!", completion = "Das verstehe ich nicht... Die Portale sind geschlossen und dennoch greifen Skovalds Dämonentruppen weiter die Tore an!\n\nWir müssen herausfinden, wo sie herkommen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40004] = { id = 40004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rückgrat brechen", description = "Um seine verderbten Truppen anzuführen, hat der Gottkönig mächtige Dämonen zu seinen Leutnants ernannt. Wenn wir den Angriff beenden wollen, müssen wir ihre Anführer ausschalten.\n\nFür normal Sterbliche sind diese Dämonen viel zu mächtig. Euch aber steht die Macht Sturmheims zu Verfügung. Sie werden keine Chance gegen Euch haben. \n\nSchaltet sie aus, um Skovalds Kommandostruktur das Rückgrat zu brechen!", sourceObjective = "Besiegt Garzareth, Karuas, Muorg und Ravathes bei der Pforte der Tapferkeit.", completion = "Nach dem Tod der dämonischen Anführer werden die Truppen des Gottkönigs auseinanderbrechen.\n\nUnd trotzdem sind wir hier noch nicht fertig. Solange die Dämonen weiter die Tore angreifen, ist Sturmheim noch nicht gerettet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40005] = { id = 40005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmheims Rettung", description = "Augenscheinlich waren die Portale, die wir hier zerstört haben, nicht die Einzigen ihrer Art. Von oberhalb der Pforte der Tapferkeit dringen weitere Dämonen ein, beschworen vom Gottkönig selbst!\n\nSkovald kann ich allein nicht besiegen. Kommt mit mir, Champion! Lasst uns den Kampf mit ihm aufnehmen und diese Bedrohung ein für alle Mal beenden!\n\nFür Sturmheim!", sourceObjective = "Besiegt Gottkönig Skovald bei der Pforte der Tapferkeit.", completion = "Es ist bedauernswert, dass der Gottkönig entkommen ist, doch durch seine Niederlage kommen weniger Legionstruppen nach Sturmheim.\n\nDie Hallen der Tapferkeit erwarten Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[40008] = { id = 40008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da müsst Ihr durch", description = "Ich muss Euch einiges erklären, aber hier ist es nicht sicher. Ich kann diese Barriere nicht ewig aufrechterhalten.\n\n<Thalyssra setzt sich ein zierliches Fläschchen an die Lippen. Ihre Augen schimmern, als sie einen Schluck daraus nimmt.>\n\nWenn wir weiter vorstoßen, finden wir da oben vielleicht einen Unterschlupf.", sourceObjective = "Bringt Thalyssra in Sicherheit.", completion = "Ihr versteht zu kämpfen.\n\nVielleicht sollte ich mich jetzt erst einmal vernünftig vorstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40009] = { id = 40009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arkaner Durst", description = "Mein Volk hat sich über Jahrtausende vom Nachtbrunnen genährt. Das uralte Mana ist unser Lebensblut und ohne es werden wir zu... nun, Ihr habt sie ja selbst da draußen gesehen.\n\n<Thalyssra hebt das Fläschchen hoch und schüttelt sanft die letzten Tröpfchen los.>\n\nIch bin heute wohl etwas leichtfertig gewesen.\n\nMeine Sinne schwinden bereits. Ohne Magie, mit der ich mich nähren kann, werde ich mich verwandeln.\n\nBitte... findet etwas, womit ich mich nähren kann... egal was...", sourceObjective = "Betretet Shal'Aran und findet etwas, um Thalyssras Durst zu löschen.", progress = "<Thalyssras Augen sind ganz trübe und ihr Körper zuckt unkontrolliert.>", completion = "<Thalyssra nimmt die Kristalle mit zitternder Hand entgegen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40010] = { id = 40010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Leylinien anzapfen", description = "Der Arkus wurde gebaut, um die magischen Leylinien unterhalb von Suramar anzuzapfen. Als wir gelernt hatten, uns vom Nachtbrunnen zu nähren, wurden die alten Einrichtungen nicht mehr gebraucht.\n\nDiese Kammer bezieht ihre Energie offensichtlich von einem anderen Ort.\n\nMomentan ist es nur eine geringe Menge, aber wenn Ihr mehr Leylinienenergie hierherleiten könntet, könnten wir uns von ihr ernähren.\n\nDie nächstgelegene Quelle befindet sich im Norden in der Nähe der Anorasenke.", sourceObjective = "Erforscht die Anorasenke und sucht nach der Leystation dort.", completion = "Und wer seid Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[40011] = { id = 40011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oculeths Werkstatt", description = "Wir müssen Großtelemant Oculeth kontaktieren, den Mann, der das Teleportationsnetzwerk von Suramar entwickelt hat.\n\nOculeth hatte im alten Suramar eine Werkstatt aus der Zeit vor der Zerschlagung. Möglicherweise hat er dort Zuflucht gesucht.\n\n<Thalyssra drückt Euch eine kleine Münze in die Hand.>\n\nZeigt ihm das, wenn Ihr ihn findet. Hoffentlich seht Ihr ihn, bevor er Euch sieht...", sourceObjective = "Gebt Großtelemant Oculeth das Abzeichen der Ersten Arkanistin.", completion = "Ihr könnt mich zu Thalyssra bringen, sobald meine Arbeit hier getan ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[40012] = { id = 40012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein alter Verbündeter", description = "Ich war unterwegs zum Zinnobertal, weil ich gehofft hatte, hier einen alten Kollegen zu finden.\n\nArkanist Kel'danath war immer fasziniert von den Verdorrten. Er hat sie jahrelang studiert und immer geglaubt, ihre wilde Natur zähmen oder sie sogar heilen zu können.\n\nAber als einer von ihnen entkommen konnte und in den königlichen Gärten Amok lief, zwang man Kel'danath, seine Forschungen einzustellen und alle Verdorrten in seiner Obhut umzubringen. Als er sich weigerte, wurde er verbannt.\n\nWenn Kel'danath noch lebt, hält er sich in der Nähe von Verdorrten auf. Und die Verdorrten zieht es immer zu alten Siedlungen wie der im Zinnobertal.", sourceObjective = "Sucht nach dem Unterschlupf von Arkanist Kel'danath im Zinnobertal.", completion = "<Hier hat bis vor Kurzem noch jemand gelebt. Auf der Schriftrolle befinden sich warm leuchtende Schriftzüge, die Eure Hand anzuziehen scheinen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40013] = { id = 40013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aethrilprobe", description = "Dieses Kraut hat eindeutig die Magie des Landes absorbiert. Es lassen sich Spuren von Leyenergie von der Wurzel bis zum Blatt feststellen.\n\nEure Kräuterkundelehrerin in Dalaran hat sicherlich Interesse daran.", sourceObjective = "Bringt die Aethrilprobe zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Auf den ersten Blick wirkt dieses Kraut so grazil und zerbrechlich... tatsächlich ist es jedoch sehr robust.\n\nOh, schaut Euch die mal an!", sourceObjectiveStatus = "unverified-source-field" }
quests[40014] = { id = 40014, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sterilisierung mit dem Spaten", description = "Stängel, Blätter und Blüten sind sicher faszinierend... aber die Staubfäden und Reproduktionsorgane in der Mitte der Blüte sind wirklich einzigartig. Sie enthalten mehr Energie als der gesamte Rest der Pflanze.\n\nIch denke, wir können Aethril verantwortungsvoller und effizienter sammeln, wenn wir uns auf diese Teile konzentrieren.\n\nDiese Blüte scheint allerdings beschädigt zu sein. Um sicherzugehen, brauche ich unbeschädigte Teile.", sourceObjective = "Beschafft einen makellosen Blütenstempel und ein unangetastetes Staubgefäß.", progress = "Es kommt einem fast grausam vor, diese... \"intimen\" Teile der Pflanze zu entnehmen. Aber keine Sorge, sie wachsen wieder nach.\n\nGenau wie bei einem Troll.", completion = "<Eure Lehrerin sieht sich Blütenstempel und Staubgefäß an und ist sichtlich beeindruckt.>\n\nDie Erdenmutter muss einen gönnerhaften Tag gehabt haben, als sie das Aethril schuf.\n\nKonzentriert Euch weiter auf diesen Teil der Pflanze, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40015] = { id = 40015, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerlumpte Seidenstreifen", description = "In feine Streifen gerissener Stoff, der schon verwittert und ganz dreckig ist. Das sind klare Hinweise auf die Verdorrten.\n\nDiese wilden und degenerierten Ausgestoßenen der Nachtgeborenen scheinen auch Aethril zu sammeln. Aber warum...?", sourceObjective = "Sprecht mit Kuhuine Sanftschreiter über Aethril und die Verdorrten.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt Hinterlassenschaften der Verdorrten nahe einer Aethrilblume gefunden?\n\nHm... Ihr seid heute schon der Dritte.", sourceObjectiveStatus = "unverified-source-field" }
quests[40016] = { id = 40016, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzweiflung macht erfinderisch", description = "Ich glaube, wir können diesen Hinweis zu unserem Vorteil nutzen, {name}.\n\nDie Verdorrten dürsten immerzu nach Mana und lassen sich in ihrer Gier kaum aufhalten. Wir könnten beobachten, wie sie das Aethril verwenden und daraus Schlüsse ziehen, um unsere eigenen Sammelmethoden zu verbessern.", sourceObjective = "Beschafft 6 zerkaute Aethrilhalme von den Verdorrten in Azsuna.", progress = "Ich bin froh, dass Ihr immer wieder in meinen Laden zurückkommt, {name}. Im Umgang mit Waffen bin ich ziemlich nutzlos. Wir brauchen Abenteurer wie Euch, um solche Fälle zu lösen.", completion = "<Eure Lehrerin sieht sich die Halme an und befühlt die Bissspuren.>\n\nAlso, die haben da wirklich alles rausgeholt, was ging.\n\nUnd wenn man genauer hinschaut, sieht man, dass sie sich vor allem auf den Mittelstrang des Halms konzentriert haben, um die Energie herauszusaugen...", sourceObjectiveStatus = "unverified-source-field" }
quests[40017] = { id = 40017, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reibungskraft", description = "Beim Einsammeln des Aethrils reibt Ihr versehentlich mit Euren Händen die Bestäubungsorgane der Pflanze aneinander und ruft so eine Reaktion hervor.\n\nVielleicht habt Ihr ja eine neue Kräuterkundetechnik entdeckt. Ihr solltet am besten mit Eurer Lehrerin in Dalaran darüber sprechen.", sourceObjective = "Sprecht mit Kuhuine Sanftschreiter über die schnelle Reproduktionsmethode für Aethril.", completion = "<Kuhuine hört sich Eure Geschichte über das Aethril an.>\n\nIhr scheint recht zu haben, {name}. Ich habe von Kräuterkundigen gehört, die ihre Blumen zur schnellen Reproduktion getrieben haben, aber mir selbst ist dies nie gelungen.\n\nGut gemacht, Kräuterkundiger. Ich bin sehr stolz auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[40018] = { id = 40018, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traumlaubprobe", description = "Dieses Kraut ist strahlend grün, papierdünn und etwas klebrig.\n\nEure Kräuterkundelehrerin in Dalaran hat sicherlich Interesse daran.", sourceObjective = "Bringt die Traumlaubprobe zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Ich kenne dieses Kraut. Ich habe es schon einmal gesehen: im Tal der Vier Winde in Pandaria.\n\nDas ist Traumlaub.", sourceObjectiveStatus = "unverified-source-field" }
quests[40019] = { id = 40019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein empathisches Kraut", description = "Aber irgendetwas an diesem Traumlaub ist anders. Es ist weniger rein.\n\nIch habe eine Theorie.\n\nDie Wildnis von Val'sharah ist von einer alptraumartigen Seuche heimgesucht worden. Und empfindliche Kräuter wie dieses reagieren vielleicht stärker auf so eine Seuche.\n\nIch benötige mehr Informationen, bevor ich mich festlegen kann. Sucht ein paar gesunde und ein paar pestbefallene Proben, damit wir unsere Nachforschungen fortsetzen können.", sourceObjective = "Beschafft 15 Proben gesundes Traumlaub und 5 Proben pestbefallenes Traumlaub.", progress = "Die armen Pflanzen...", completion = "Genau, wie ich vermutet hatte. Dieses infizierte Kraut stirbt... aber vielleicht können wir diese Erkenntnis zu unserem Vorteil nutzen.\n\nSchaut, Kräuterkundiger: Das sterbende Traumlaub ist voller Kräuterextrakte. Aus gesundem Traumlaub lässt sich nicht so viel gewinnen, aber diese infizierten Exemplare bieten enorme Mengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40020] = { id = 40020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verderbt bis in den Tod", description = "Die Verderbnis hat sich dieses Krauts vollkommen bemächtigt.\n\nDiese Pest ist eine seltsame Macht, dessen Natur das in der herkömmlichen Kräuterkunde vermittelte Wissen weit übersteigt. Um zu verstehen, was hier vor sich geht, müsst Ihr Euch an einen Experten auf diesem Gebiet wenden.", sourceObjective = "Findet jemanden in Lorlathil, der Euch über die Wirkungen dieser Pest auf die Kräuter aufklären kann.\n\nBereitgestellter Gegenstand:", completion = "Eine weitere Pflanze ist gefallen...\n\n<Der {class} versucht vergeblich, die Tränen zurückzuhalten.>\n\nVERDAMMTER ALPTRAUM! VERDAMMT SOLL ER SEIN!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[40021] = { id = 40021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine tote Pflanze zu viel", description = "Für diese Grausamkeit müssen wir RACHE üben. Ich verstehe ja, dass der Smaragdgrüne Traum und der Alptraum im Gleichgewicht sein müssen, doch dieses Mal ist seine Verderbnis einfach ZU WEIT gegangen!\n\nIch wette, das waren die Satyrn. Lasst sie büßen! Elune wird Euch dafür belohnen.", sourceObjective = "Tötet 20 Satyrn in Val'sharah.", completion = "Ich spüre, wie sich die Verderbnis zurückzieht. Das ist gut.\n\nSie wird wiederkommen, aber seht nur... Das Traumlaub hat weitere seiner Geheimnisse preisgegeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40022] = { id = 40022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Alptraum erstickt", description = "Noch eine Pflanze ist der Verderbnis zum Opfer gefallen. Diese hier hat sich so stark zusammengerollt, dass das Sonnenlicht sie nicht mehr erreichen konnte.\n\nIhr solltet sie zu Windwirker Osme in Lorlathil bringen. Er wird nicht erfreut darüber sein.", sourceObjective = "Bringt das pesterstickte Kraut zu Windwirker Osme in Val'sharah.\n\nBereitgestellter Gegenstand:", completion = "<Osme sieht sich das Kraut an.>\n\n<Einen Moment lang ist er ganz still.>\n\nNEEEEEEEEEIIIIIIIIN!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[40023] = { id = 40023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Namen der Pflanzen", description = "Unser Kreuzzug gegen diese Verderbnis darf nicht scheitern, {name}.\n\nDas ist unsere heldenhafte Pflicht als Kräuterkundige.\n\nAls Kräuterkrieger.\n\nEs reicht nicht, einfach nur ein paar Satyrn zu töten. Wir müssen ihre Anführer ausschalten. Bringt dieses gefallene Kraut nach Shala'nir im Nordosten. Findet Tur'xorans Beschwörungsstein, legt dieses Kraut davor auf den Boden und dann... dann reißt ihm den Kopf ab.\n\nIm Namen der Pflanzen.", sourceObjective = "Verwendet Tur'xorans Beschwörungsstein, um Tur'xoran herbeizubeschwören und zu töten.", completion = "Danke für Euer tapferes Eingreifen, {name}.\n\nWenn Ihr Euch das nächste Mal einem Traumlaubzweig nähert, wird Euch womöglich das Land selbst dafür danken.", sourceObjectiveStatus = "unverified-source-field" }
quests[40024] = { id = 40024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuchsblumenprobe", description = "Irgendetwas an diesem Kraut ist besonders... sagt Euch Eure Nase.\n\nEure Kräuterkundelehrerin in Dalaran wäre sicherlich an ein paar Proben dieser außergewöhnlichen neuen Pflanze interessiert.", sourceObjective = "Sammelt 20 Fuchsblumenproben und bringt sie dann zu Kuhuine Sanftschreiter in Dalaran.", progress = "<Die Tauren schnuppert die Luft.>", completion = "Mir gefällt dieses Kraut, {name}. Es erinnert mich ein bisschen an die Gorgrondfliegenfalle: Beide scheinen die Nase anzugreifen.\n\nSchaut, wenn Ihr das Kraut auf diese Weise einsammelt, erhaltet Ihr mehr davon...", sourceObjectiveStatus = "unverified-source-field" }
quests[40025] = { id = 40025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Anbeißen", description = "An diesem Kraut hat eines der einheimischen Tiere geknabbert.\n\nAber welche Tiere fressen schon Fuchsblumen? Bären?\n\nVielleicht weiß Eure Lehrerin in Dalaran mehr darüber.", sourceObjective = "Bringt den angenagten Fuchsblumenhalm zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Stimmt, {name}. Irgendetwas hat auf diesem Kraut herumgekaut.", sourceObjectiveStatus = "unverified-source-field" }
quests[40026] = { id = 40026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf den Blumenbeißer", description = "Das ist ein mächtiges Kraut, {name}. Die Tiere fressen manchmal ein paar einfache Kräuter, aber so potente Pflanzen meiden sie normalerweise.\n\nFaszinierend... Welche Tiere fressen wohl Fuchsblumen? Elche?\n\nIhr solltet das untersuchen. Findet heraus, welches Tier die Fuchsblumen frisst, und versucht, ihm ein paar dieser Blumen aus dem Maul zu reißen, bevor es entkommt.", sourceObjective = "Findet heraus, welches Tier die Fuchsblumen frisst, jagt es und entreißt ihm 12 zerkaute Fuchsblumenstücke.", progress = "Habt Ihr herausgefunden, welche Tiere Fuchsblumen fressen? Ziegen? Biber? Nachtsäbler?", completion = "Füchse also.\n\nHm.\n\nAber das ergibt Sinn. Ich hätte wohl von selbst drauf kommen sollen.\n\nSo, jetzt habe ich mich genug blamiert. Schauen wir doch mal, was es hier sonst noch herauszufinden gibt...", sourceObjectiveStatus = "unverified-source-field" }
quests[40028] = { id = 40028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verführerische Düfte", description = "Während Ihr die letzten Fuchsblumen einsammelt, bemerkt Ihr einen speziellen Teil der Pflanze.\n\nEines der Blätter weist einen kleinen Wulst auf, genau am Übergang zum Stängel. Ihr untersucht diese Stelle und kommt zu dem Schluss, dass dies der Ursprung des besonderen Duftes der Fuchsblume ist.\n\nEure Kräuterkundelehrerin wäre sicherlich sehr daran interessiert.", sourceObjective = "Bringt die Fuchsblumenduftdrüse zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "<Kuhuine schnuppert an der kleinen Drüse.>\n\nDas ist in der Tat eine Duftdrüse. In alchemistischer Hinsicht scheint sie fast wertlos zu sein... Aber immerhin scheint sie diese Füchse anzulocken.\n\nWenn Ihr diese Drüse auspresst, werdet Ihr sicher den einen oder anderen neuen Freund anlocken können.", sourceObjectiveStatus = "unverified-source-field" }
quests[40029] = { id = 40029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fjarnskagglprobe", description = "Wer sich mit der Kräuterkunde nicht sonderlich auskennt, könnte diesen Dornenbusch als komplett nutzlos erachten. Durch Eure Ausbildung wisst Ihr aber, dass es sich um eine sehr spezielle Pflanze handelt.\n\nEure Kräuterkundelehrerin in Dalaran wäre sicherlich an ein paar weiteren Proben interessiert.", sourceObjective = "Bringt 20 Proben Fjarnskaggl zu Kuhuine Sanftschreiter in Dalaran.", progress = "Was habt Ihr denn da, Kräuterkundiger?", completion = "Ein fantastischer Fund, {name}. Das muss das berühmte Vrykulkraut Fjarnskaggl sein. Bisher habe ich nur in Büchern davon gelesen!\n\nIch werde mit Euch teilen, woran ich mich erinnere...", sourceObjectiveStatus = "unverified-source-field" }
quests[40030] = { id = 40030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Widderhornschaufel", description = "Die Runenmarkierungen auf dem Griff des Werkzeugs lassen darauf schließen, dass es von einem Kräuterkundigen der Vrykul stammt.\n\nOffensichtlich sammeln auch die Vrykul diesen Fjarnskaggl. Eure Lehrerin, Kuhuine, erwähnte, dass sie früher etwas darüber gelesen habe.\n\nVielleicht möchte sie die Werkzeuge sehen, mit denen die Vrykul diese Pflanze ernten.", sourceObjective = "Bringt die Widderhornschaufel zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Und die habt Ihr in der Nähe eines Fjarnskagglbusches gefunden?", sourceObjectiveStatus = "unverified-source-field" }
quests[40031] = { id = 40031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kräuterwissen der Vrykul", description = "<Kuhuine sieht sich die Kelle genau an.>\n\nDas ist ein einfaches Grabwerkzeug. Da kann man nicht viel von lernen... wobei...\n\nJa, es weist darauf hin, dass die Vrykul heutzutage IMMER NOCH dieses Kraut sammeln.\n\nDie Vrykul wissen sicherlich mehr darüber als wir. Jetzt müssen wir nur noch herausfinden, wo sie ihr Wissen verwahren.", sourceObjective = "Findet drei Kräuterkundebücher der Vrykul in Sturmheim.", progress = "Habt Ihr die Bücher schon finden können, {name}?", completion = "Dieses Buch, das \"Kräuterwissen der Uralten\", scheint sehr interessant zu sein, aber es fehlen ein paar Seiten. Das ist wirklich zu schade.\n\nTrotzdem kann man viel daraus lernen.\n\n<Kuhuine schlägt das Buch in der Mitte auf und blättert dann ein paar Seiten zurück...>\n\nSeht Euch mal diese Technik hier an!", sourceObjectiveStatus = "unverified-source-field" }
quests[40032] = { id = 40032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die fehlende Seite", description = "<Diese Seite scheint aus einem größeren Buch herausgerissen worden zu sein. Dort steht:>\n\n\"...das Steinmal an der See, einen von der Liebe der Götter gesegneten Ort.\n\nEr legte seine Opfergabe aus Fjarnskaggl zu Füßen des Steinhaufens nieder, wisperte die Worte 'Kräuter bringen Kräuter hervor' und empfing den gewünschten Segen.\"\n\nDies könnte zu dem Buch gehören, das Ihr Eurer Kräuterkundelehrerin mitgebracht habt.", sourceObjective = "Bringt die runenübersäte Tagebuchseite zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Was für ein Glück! Diese Seite passt perfekt zu dem Buch, das Ihr für mich besorgt habt. Jetzt müssen wir sie nur noch zusammenfügen und...", sourceObjectiveStatus = "unverified-source-field" }
quests[40033] = { id = 40033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fjarnskaggl", description = "Fertig! Es scheint da einen Kräuterkundigen der Vrykul namens Torgus gegeben zu haben, der eine Opfergabe aus Fjarnskaggl an einem Steinhaufen an der Küste – wahrscheinlich in Sturmheim – abgelegt und dadurch den Segen seiner Vorfahren erlangt hat.\n\n<Kuhuine zuckt mit den Schultern.>\n\nKönnte einen Versuch wert sein. Aber da wir nicht genau wissen, auf was Ihr Euch da einlasst, solltet Ihr vielleicht ein paar Freunde mitnehmen.Ihr erlernt:", sourceObjective = "Bringt 20 Zweige Fjarnskaggl zum verwitterten Steinhaufen in Sturmheim und empfangt dann den Segen des Fjarnskaggl.", sourceObjectiveStatus = "unverified-source-field" }
quests[40034] = { id = 40034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sternlichtrosenstaub", description = "Trotz Eurer guten Ausbildung löst sich die Rose einfach in Eurer Hand auf.\n\nEure Kräuterkundelehrerin in Dalaran möchte sicher einen Blick darauf werfen.", sourceObjective = "Bringt den Sternlichtrosenstaub zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Dieses Kraut hat sich einfach in Eurer Hand aufgelöst?\n\nFaszinierend...", sourceObjectiveStatus = "unverified-source-field" }
quests[40035] = { id = 40035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaaanz sachte", description = "Leider kenne ich keine Spezialtechniken, die Euch dabei helfen könnten. Ihr müsst es einfach selbst probieren, indem Ihr da rausgeht und beim Umgang mit Sternlichtrosen möglichst sanft vorgeht.", sourceObjective = "Versucht, 15 weitere Sternlichtrosen zu ernten.", completion = "Habt Ihr Erfolg gehabt? Nein?\n\nSelbst wenn nicht, so übt Ihr doch Eure Techniken. Nicht aufgeben, Kräuterkundiger.", sourceObjectiveStatus = "unverified-source-field" }
quests[40036] = { id = 40036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Juwelenbesetzter Spatenstiel", description = "Ein reich verzierter Spatenstiel liegt direkt neben der Rose. Offensichtlich war der Spaten hübscher, als er robust war, denn das Spatenblatt ist einfach abgefallen.\n\nEure Kräuterkundelehrerin würde sich das bestimmt gerne ansehen.", sourceObjective = "Bringt den juwelenbesetzten Spatenstiel zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Den habt Ihr neben einer Sternlichtrose gefunden?\n\nIhr Abenteurer findet wirklich immer so interessante Sachen da draußen in der Natur...", sourceObjectiveStatus = "unverified-source-field" }
quests[40037] = { id = 40037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Spatenblatt", description = "Habt Ihr die Inschrift auf dem Stiel gesehen, {name}? Da steht \"Kräuterkundiger Tharillon\" in der Schrift der Nachtgeborenen.\n\nMit dem Stiel können wir nicht viel anfangen, aber vielleicht können wir mithilfe des Blattes lernen, die Sternlichtrose erfolgreicher abzuernten.\n\nIch würde mit der Suche in Suramar beginnen.", sourceObjective = "Findet das zerbrochene Spatenblatt eines Kräuterkundigen.", progress = "Was macht die Suche?", completion = "Das Spatenblatt ist verzaubert... aber das war ja eigentlich klar. Ich bin mir sicher, dass wir diesen Zauber hier in Dalaran nachstellen können.\n\nSchade, dass dieser Kräuterkundige nicht sonderlich umgänglich war. Wir hätten sicher viel von ihm lernen können. Aber zumindest ist er noch am Leben, irgendwo da draußen...", sourceObjectiveStatus = "unverified-source-field" }
quests[40038] = { id = 40038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahnsinniges Gebrabbel", description = "Von den auf dreckiges Pergament geschriebenen zornigen Phrasen sticht Euch ein Teil besonders ins Auge:\n\n\"...denkt, <ER/SIE> kennt sich mit Kräutern aus...\n...{name}{name}\n{name}{name} hat mein Spatenblatt gestohlen...\n...werde <ihm/ihr> die verdammte KEHLE durchschneiden, wenn...\n\n...brauche jetzt nur noch...\n...etwas mehr Mana...\n...vielleicht Aethril, ja...\"\n\nEure Kräuterkundelehrerin hat bestimmt Interesse an diesen Zeilen.", sourceObjective = "Bringt den hingekritzelten Unfug zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Oha. Da ist jemand wirklich wütend auf Euch.\n\nMeint Ihr, diese Worte sind von dem nachtgeborenen Kräuterkundigen, dem Ihr... begegnet seid?", sourceObjectiveStatus = "unverified-source-field" }
quests[40039] = { id = 40039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tharillons Niedergang", description = "Er erwähnt Euren Namen... sein Spatenblatt... Aethril...\n\nDas muss von dem Kräuterkundigen Tharillon stammen. Und er scheint dem Fluch der Nachtsüchtigen verfallen zu sein. Außerdem ist er auf der Suche nach Aethril, vermutlich irgendwo in Azsuna.\n\nTharillon ist zurzeit unsere einzige Hoffnung, mehr über die Sternlichtrose zu lernen. Spürt ihn auf. Aber nehmt lieber ein paar Freunde mit, denn er wird sich vermutlich nicht kampflos ergeben.", sourceObjective = "Nehmt 20 Häufchen Sternlichtrosenstaub mit nach Azsuna, um damit den Kräuterkundigen Tharillon aus seinem Versteck zu locken. Durchsucht ihn dann nach Informationen über Kräuterkunde.", progress = "Möge die Erdenmutter Euch begleiten, {name}.", completion = "Fantastische Arbeit, {name}! Mit diesem Wissen werden wir nie wieder Sternlichtrosenstaub in unseren Händen halten müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[40040] = { id = 40040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelswurzprobe", description = "Dieses Kraut scheint bis in die Blattspitzen mit verderbter Energie erfüllt zu sein. Es fühlt sich kalt, glatt und trocken an, doch ist die Berührung ziemlich schmerzhaft.\n\nEure Kräuterkundelehrerin in Dalaran möchte sicher einen Blick darauf werfen.", sourceObjective = "Bringt die Teufelswurzprobe zu Kuhuine Sanftschreiter in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Oh. Dieses Kraut mag ich gar nicht. Ich finde es faszinierend, aber ich mag es nicht.\n\n<Kuhuine sieht sich die Mitte der Pflanze an.>\n\nWerft einen Blick auf diese Samen, {name}. Wir können sie verwenden. Achtet darauf, sie beim nächsten Mal vorsichtig einzusammeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[40041] = { id = 40041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelswurzanalyse", description = "Ich habe Teufelswurzproben an einige Kräuterkundekollegen geschickt, doch noch keine Nachricht von ihnen erhalten. Würdet Ihr sie aufsuchen und mir ihre Analysen bringen?\n\nRyno Blumenfeld arbeitet zurzeit im Krater von Un'Goro.\n\nDani Gründaum erforscht gerade Freyas Einfluss im Sholazarbecken.\n\nUnd Lohor war in der überwucherten Gegend von Gorgrond beschäftigt.", sourceObjective = "Sammelt Ryno Blumenfelds, Dani Gründaums und Lohors Analysen ein.", progress = "Danke, dass Ihr bereit seid, diese Reise auf Euch zu nehmen, {name}.", completion = "Zum größten Teil ist das alles sehr technisch und banal, aber Rynos Analyse kann direkt in die Praxis umgesetzt werden.\n\nSchaut mal hier...", sourceObjectiveStatus = "unverified-source-field" }
quests[40042] = { id = 40042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Teufelswurzmeisterschaft", description = "Ich habe eine Idee, wie wir Teufelswurz besser ernten können, {name}. Seht Ihr, wenn man verstehen will wie etwas entsteht, muss man sich manchmal aus einer anderen Richtung herantasten.\n\nIch habe kürzlich erfahren, dass Cenarius, einer unserer ehrwürdigsten Götter, von einer Verderbnis befallen wurde. Zweifellos dieselbe Verderbnis, die auch diesen Kräutern innewohnt.\n\nWenn Ihr herausfinden könnt, wie diese Verderbnis funktioniert und einen Weg findet, sie zu neutralisieren, könnten wir diese Methode vermutlich auch zur Ernte dieser Pflanzen anwenden.", sourceObjective = "Reist zum Smaragdgrünen Alptraum und heilt die Verderbnis, die Cenarius befallen hat. Bringt was immer ihr findet zurück zu Kuhuine in Dalaran.", progress = "Ich hoffe, Ihr nehmt einige Freunde mit auf diese Reise, denn das könnte Eure bisher größte Prüfung sein.", completion = "<Kuhuine nimmt behutsam die Saat von Euch entgegen und hört sich Eure Geschichte über die Heilung von Cenarius an.>\n\nFaszinierend! Wenn das wahr ist, können wir Teufelswurz auf ähnliche Weise ernten. Gut, hört zu...", sourceObjectiveStatus = "unverified-source-field" }
quests[40043] = { id = 40043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Heldenjäger", description = "Helya hat meinen Orden zum Gespött gemacht, indem sie die \"Helarjar\" erschaffen hat. Diese mächtigen Untoten machen Jagd auf die Heldenkrieger und entreißen ihnen die Seelen, bevor meine Val'kyr sie sich nehmen können. Unter ihnen befindet sich auch ihr persönlicher Champion, Vigfus Klingenwind, der mit gestohlenen Klingen kämpft, die ich einst selbst geschmiedet habe.\n\nEr ist mit einer Ladung gestohlener Seelen, die er nach Helheim bringen will, zum Wellenskornhafen zurückgekehrt. Begebt Euch dorthin, tötet ihn und seine Helarjar und nehmt Euch seine Schwerter.", sourceObjective = "Besiegt Vigfus Klingenwind und seine Truppen und nehmt ihm die Klingen ab.", progress = "Ah, Ihr seid zurückgekehrt...", completion = "Verdammte Helya! Sie hat diese Klingen verderbt! Aber immerhin ist ihr Champion besiegt, die Helarjar kriechen zurück nach Helheim und die Waffen befinden sich in den Händen MEINES Champions! Und sie hat sie sogar mächtiger gemacht, als sie zuvor waren. Nutzt ihre Macht weise, {name}, und löscht die Feinde dieser Welt aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[40044] = { id = 40044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten im Nebel", description = "Viele der Kvaldir hier in der Bucht sind frühere Bewohner des Hafens, die von der Seehexe Helya verflucht wurden und ihr für alle Zeit zu Willen sein müssen.\n\nDie, von denen Ihr lest, wandeln immer noch durch das träge Wasser. Eine gütige Seele könnte ihnen mit der Spitze einer Klinge eine Atempause verschaffen.\n\nSagt, wie gütig ist Eure Seele?", sourceObjective = "Besiegt Kapitän Sten, Sigrid, Kjell und Halvir im Höllenschlundmorast.", completion = "Ihre Schinderei ist vorüber, und einige Kvaldir weniger durchstreifen das Land von Sturmheim.\n\nBeides betrachte ich als Segen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40045] = { id = 40045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sozialisierung der Kaulquappen", description = "Die Murlocs liegen mir viel zu sehr am Herzen, als dass ich Euch auftragen würde, alle erwachsenen Murlocs einfach umzubringen.\n\nStattdessen sollten wir die nächste Generation dazu bringen, etwas friedlicher zu sein. Murky ist dafür das beste Beispiel.\n\nBringt ihn dazu, mit den Murlockaulquappen zu sprechen und sie zu unseren Verbündeten zu machen.", sourceObjective = "Sprecht mit 10 Kaulquappen der Sumpfsteine.", completion = "Murky hat mittlerweile ganz schön viele Anhänger, was? Vielleicht können sie ihm ja helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40046] = { id = 40046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Untiefen plündern", description = "Die Kvaldir leben, um Odyn das Leben schwer zu machen. Hier verrichten sie ihr gehässiges Werk. Sie stehlen die Seelen der Lebenden, die bisher nicht gerichteten Seelen, und berauben Odyn so seiner Champions.\n\nSie bringen sie hierher, um sie zu Helya zu schicken, doch die Nebel verhüllen jeden Hinweis drauf, wie dies vonstattengeht.\n\nIhr scheint gut mit Nebel zurechtzukommen. Vielleicht könnt Ihr die Wracks in der Bucht untersuchen und die Antwort finden. Ihr Fremden scheint ein Talent dafür zu haben, auch den verborgensten Geheimnissen auf die Spur zu kommen.", sourceObjective = "Durchsucht die Schiffswracktrümmer im Höllenschlundmorast nach Havis Hinweis.", progress = "Habt Ihr Antworten entdeckt oder weitere Fragen?", completion = "Die Naglfar...\n\nDas heißt also, Helyas Kvaldir können im Nebel navigieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[40047] = { id = 40047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kugelrund fressen", description = "Murky ist mein absoluter Liebling. Um aber eine Veränderung in der hiesigen Murlocpopulation zu bewirken, benötigt er besondere Fähigkeiten.\n\nIn diesen Gewässern gibt es eine Menge Kugelfische und ich glaube, dass sie ein gutes Mittel für ihn darstellen werden.\n\nTötet ein paar von ihnen und sammelt ihre Eier für Murky ein.", sourceObjective = "Sammelt 5 Portionen Kugelfischlaich ein.", progress = "Kugelfische haben diese unglaubliche Veranlagung... zu explodieren. Damit könnten sie ein wichtiges Werkzeug für Murky darstellen.", completion = "Kugelfische sind das perfekte Mittel für Murky! Ich stelle nur schnell einen Zauber zusammen, um sie schneller wachsen zu lassen.\n\nDann muss er sie nur noch werfen und... BUMM!", sourceObjectiveStatus = "unverified-source-field" }
quests[40048] = { id = 40048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fäden des Marionettenspielers", description = "Ich weiß, dass Ihr nur gekommen seid, um die Pergamente abzuliefern, aber wir könnten hier jemanden mit Euren Fähigkeiten brauchen, {class}. Unsere Truppen haben genug damit zu tun, die Dämoneninvasion aufzuhalten. Wir können zurzeit niemanden tiefer in das Lager der Feinde hineinschicken.\n\nDie stärksten ihrer Krieger halten sich im Hintergrund und befehligen ihre Dämonen an der Front mithilfe verzauberter Runen.\n\nIch würde mir sehr gern eine dieser Runen ansehen. Wenn Ihr mir eine bringen könntet, würde ich daraus etwas lernen und gegen die Legion einsetzen können.", sourceObjective = "Besorgt eine Rune der Vorherrschaft von den Dämonen der Legionsbasis: Chaos.", progress = "Habt Ihr schon ein paar Runen gefunden?", completion = "Ja, die meinte ich.\n\n<Jace dreht die Rune in seiner Hand und schaut sich die komplexen Inschriften an.>\n\nAusgezeichnete Arbeit, {name}. Ich werde mich bei Nalthanis für Euch aussprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40049] = { id = 40049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schleimzeit", description = "Murky wächst schnell heran und muss tüchtig essen! Und was gibt es Besseres als Schleimgras für einen jungen Murloc?\n\nIn den Murlocgewässern hier findet Ihr jede Menge davon! Ihr müsst nur hindurchschwimmen und Murky damit füttern!", sourceObjective = "Füttert Murky mit 6 Bündeln Schleimgras, indem Ihr durch sie hindurchschwimmt.", completion = "Dank des Schleimgrases scheint Murky sehr ausgeprägte Schleimfähigkeiten erlangt zu haben. Das ist fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[40050] = { id = 40050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schiffbruchgrotte" }
quests[40051] = { id = 40051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonengeheimnisse", description = "Die Dämonen haben einen entscheidenden Fehler begangen, als sie ihre Geheimnisse in diesem Buch niederschrieben. Die davon ausgehende Teufelsenergie ist überwältigend.\n\nDoch sie reicht nur für eines der Rituale. Es wird das Buch völlig verzehren.\n\nIhr entscheidet, welche Geheimnisse wir gegen die Brennende Legion einsetzen.", sourceObjective = "Lest den Folianten der Dämonengeheimnisse und entscheidet Euch für eine Spezialisierung: Verwüstung oder Rachsucht.", completion = "Überraschend. Ich stimme zu, eine ausgezeichnete Wahl, {name}.\n\nNun müsst Ihr den Rest von uns unterweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40052] = { id = 40052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uraltes Vrykul gemeistert", description = "Hier habt Ihr die Tafeln zurück, zusammen mit der entschlüsselten Schrift. Ihr könnt diesen Kodex auch zu Pallin zurückbringen. Ich werde mich darauf vorbereiten, dass er mich nach Dalaran zurückruft.\n\n<Nicholo seufzt.>\n\nLernt aus meinen Fehlern, {name}. Ich an Eurer Stelle würde versuchen, mich so schnell wie möglich von Pallins \"Bitten\" zu befreien.", sourceObjective = "Bringt die Tafeln und den Kodex zu Professor Pallin.", completion = "Also hat Nicholo es geschafft, den Kodex zu vervollständigen? Und die Tafeln sind entziffert!\n\nHmm... Das ist interessant. Auf diesen Tafeln stehen einige interessante Zaubersprüche, die wir zu unserem Vorteil nutzen könnten. Obwohl ich es persönlich etwas veraltet finde, mit Stein zu arbeiten. Ich werde sie auf ein Pergament kopieren, und Ihr dürft sie dann auf Nebenwirkungen testen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40056] = { id = 40056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere neuen Verbündeten", description = "<Schüler/Schülerin>! Die anderen Dämonenjäger in Azsuna wünschen Euch zu sehen.\n\nIch weiß, dass Ihr Zeit benötigt, um die Legion zu bekämpfen, aber Ihr dürft dennoch nicht Eure Studien vernachlässigen.\n\nIch möchte, dass Ihr während Eurer Zeit dort unten ein paar neue Glyphen für Eure Fähigkeiten erstellt.\n\nSicherlich hat meine überragende Genialität mittlerweile auf Euch abgefärbt, sodass Ihr mit den neuen Erkenntnissen Eure eigenen Vorlagen ersinnen könnt.", sourceObjective = "Meldet Euch bei Allari der Seelenfresserin in Azsuna.", completion = "{name}, schön, Euch wiederzusehen. Jemanden mit Eurer Stärke können wir immer brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40057] = { id = 40057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Macht", description = "Wie ich sehe, möchtet Ihr Eure Mächte durch Schriften verstärken. Ich glaube, dann können wir zwei Fliegen mit einer Klappe schlagen.\n\nIch brauche Hilfe dabei, die Bedrohung durch die Dämonen zu verringern. Vielleicht würden noch ein paar Kämpfe gegen unsere Feinde Euch inspirieren.", sourceObjective = "Tötet 15 Dämonen, um die Invasion zu bremsen.", completion = "Ich wünschte, ich hätte mehr wie Euch, {name}. Ihr kämpft mit großer Leidenschaft.\n\nUnd wie ich sehe, habt Ihr dazugelernt, wie Ihr Eure Fähigkeiten verstärken könnt. Ich bin sicher, Euer Meister in Dalaran wird zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40058] = { id = 40058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Symbologie der Verteidigung", description = "Wie Ihr wisst, {name}, müssen wir Dämonenjäger unsere dunkle Seite in Schach halten, damit wir ihr nicht völlig verfallen und selbst zu Dämonen werden.\n\nOben im Norden gibt es einen Dämonenjäger, der Baric Sturmläufer heißt. Er hat vor, seine Markierungen zu verstärken. Er könnte Eure Hilfe bei seinem Ritual gebrauchen.", sourceObjective = "Sucht nach Baric Sturmläufer in der Nähe der Leyruinen von Zarkhenar.", completion = "Ihr seid gekommen, um mir bei meinem Ritual zu helfen? Ich danke Euch, {name}.\n\nIn diesen Zeiten sind Verbündete wichtiger als je zuvor.", sourceObjectiveStatus = "unverified-source-field" }
quests[40059] = { id = 40059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gegensätze stoßen sich ab", description = "In den Ruinen in der Nähe gab es einen Ausbruch an Leyenergien. Verdrehte Nachtelfen, die als \"Nachtsüchtige\" angesehen werden, durchsuchen jetzt gerade das Gebiet.\n\nSammelt Leystaub für mich von den Nachtsüchtigen in den Ruinen vor uns. Der Staub ist voller Arkanenergie, die ich brauche, um mein Ritual zu beenden.", sourceObjective = "Sammelt Leystaub von den Nachtsüchtigen in Zarkhenar.", progress = "Obwohl sie Gegensätze sind, kann die eine nicht ohne die andere existieren.", completion = "Ob Ihr es glaubt oder nicht, das war der einfache Teil.\n\nDer nächste Teil wird ein wenig schwieriger... zumindest für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[40060] = { id = 40060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herr über den inneren Dämon", description = "Jetzt, da wir alle wichtigen Teile haben, können wir das Ritual beginnen.\n\nIch werde Euch jetzt instruieren, wie Ihr mir währenddessen helfen könnt. Es ist unerlässlich, dass Ihr meinen Anweisungen folgt, wenn ich sie Euch gebe, oder das Ritual wird scheitern.", sourceObjective = "Helft Baric dabei, sein Ritual zu beenden.", completion = "Es ist vollbracht. Ich fürchte, wenn ich noch länger gewartet hätte, um meine Zauberschutze zu verbessern, hätte der Dämon in mir wahrscheinlich die Oberhand gewonnen.\n\nNochmals vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40061] = { id = 40061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind kennen", description = "Wir studieren die Dämonen, während wir sie bekämpfen.\n\nAus gesammelten Informationen kann großes Verständnis erwachsen. Ich habe eine Dämonenjägerin, die gerade Informationen über die Dämonen vom Teufelsfeuervorstoß sammelt.\n\nSucht sie auf und seht, was sie über die Dämonen in Erfahrung gebracht hat, die in diese Region einfallen.", sourceObjective = "Sucht nach Zaria Schattenherz in der Nähe des Teufelsfeuervorstoßes.", completion = "Schön, Euch wiederzusehen, {name}. Kayn hat Euch geschickt, um zu sehen, was ich in Erfahrung bringen konnte?\n\nWenn das so ist, ich habe viel zu erzählen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40062] = { id = 40062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pralle Alptraumsamenkapsel", description = "<Die Blume hat sich eingerollt, um sich selbst vor der darin gefangenen Alptraumenergie zu schützen.>\n\n<Professor Pallin hätte sicherlich Interesse daran.>", sourceObjective = "Bringt die pralle Alptraumsamenkapsel zu Professor Pallin in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Kapseln wie diese bergen eine gewaltige Menge Energie. Inkorrektes Mahlen kann katastrophale Folgen für die Vorderseite eines Gewandes nach sich ziehen.\n\nWenn Ihr aber lernt, sie korrekt zu mahlen, könnt Ihr die Mahlgeschwindigkeit enorm erhöhen. Also, schaut zu und lernt, Schüler!", sourceObjectiveStatus = "unverified-source-field" }
quests[40063] = { id = 40063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kontrolle ist der Schlüssel", description = "Ich nehme an, Ihr wisst noch, weshalb Ihr Euch die Augen herausgenommen habt?\n\nObwohl wir jetzt deutlicher sehen können, haben die Dämonen Mittel und Wege gefunden, um ihre teuflischen Energien vor uns zu verbergen.\n\nEin Dämonenkommandant befindet sich unter den Truppen dort unten und kommandiert sie aus den Schatten heraus. Sein Umhang wird von einem Energiekristall gespeist.\n\nFindet und zerstört den Kristall, dann tötet den Kommandanten.", sourceObjective = "Zerstört den Kristall, der dem Aufseher Felorax Schutz gewährt, und tötet ihn dann.", completion = "Ich muss Euch loben, Schreiberin. Ihr seid eine ausgezeichnete Jägerin.\n\nNehmt diese Tinte als Lohn für Eure Mühen. Ich habe keine Verwendung dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[40064] = { id = 40064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holziger Samenknoten", description = "<Das Mahlen dieser Blume hat sich als schwieriger als normal erwiesen. In der buschigen Mitte der Blüte befindet sich ein kompakter Samenknoten.>\n\n<Professor Pallin hätte sicherlich Interesse daran.>", sourceObjective = "Bringt den holzigen Samenknoten zu Professor Pallin in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Das stammt von einer Fuchsblume? Faszinierend.\n\nAber es gibt gute Verwendungsmöglichkeiten für diese holzigen Knoten. Wenn Ihr eine holzige Blume zusammen mit anderen, weicheren Blumen mahlt, könnt Ihr den Vorgang enorm beschleunigen! Passt mal auf...", sourceObjectiveStatus = "unverified-source-field" }
quests[40065] = { id = 40065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fjarnsk", description = "<Eine schleimige Substanz tropft aus dem Inneren der Blüte. Das ist keine Tinte, sondern etwas ganz anderes...>\n\n<Professor Pallin hätte sicherlich Interesse daran.>", sourceObjective = "Bringt den Fjarnsk zu Professor Pallin in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "<Der Professor taucht seinen Finger in die Flüssigkeit und probiert davon.>\n\nOh! Ich weiß, was das ist. Die Kräuterkundler haben davon gesprochen. Es nennt sich Fjarnsk.\n\nWürgetang enthält oftmals Depots einer ganz ähnlichen Flüssigkeit. Mal sehen, ob wir einer uralten Mahltechnik auf die Sprünge helfen können...", sourceObjectiveStatus = "unverified-source-field" }
quests[40066] = { id = 40066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 032 - Blackbeak Overlook - twh" }
quests[40067] = { id = 40067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Vignette: Boulderfall - twh" }
quests[40068] = { id = 40068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Vignette: Egyl the Enduring - twh" }
quests[40069] = { id = 40069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jungwurminnereien", description = "Die Drogbar nutzen diese Höhlen, um ihre jungen Würmer zu trainieren.\n\nDie Felskriecher sind noch jung und relativ schwach, aber sie werden schon bald an Größe und Stärke zulegen. Wenn wir nicht eingreifen, reifen sie zu den Monstern heran, auf denen die Drogbar in die Schlacht reiten.\n\nIhre Innereien sind ebenfalls als sehr nützlich bekannt und ich benötige sie. Zwei Würmer mit einer Klappe, sozusagen.", sourceObjective = "Sammelt Wurminnereien von jungen Felskriechern in der Felskriecherschlucht.", progress = "Wofür ihre Innereien gut sind? Nun, das werdet Ihr noch sehen. Es mag Euch nicht gefallen, aber Ihr werdet es bald herausfinden.", completion = "Aus diesen Wurminnereien kann man hervorragend eine besondere Art von Seil fertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40070] = { id = 40070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adlereirettung", description = "Die Zahl der vom Stamm der Himmelshörner verehrten Adler schwindet.\n\nDie Drogbar füttern ihre jungen Würmer mit Adlereiern, damit diese groß und stark werden und als Schlachtreittiere dienen können.\n\nWenn die Drogbar weiterhin so viele Eier rauben, könnten die Adler aussterben.\n\nBegebt Euch runter in den tieferen Teil der Höhle und rettet so viele Adlereier wie möglich.", sourceObjective = "Begebt Euch in die Felskriecherschlucht und rettet Adlereier.", progress = "Wenn die geraubten Eier nicht gerettet werden, könnten die Adler bald aussterben.", completion = "Diese Eier sind in schlechter Verfassung, {name}. Einige haben Risse und Brüche und andere sind schon ganz kalt.\n\nAber es gibt noch Hoffnung. Ich glaube, ein paar der Eier, die Ihr bergen konntet, sind noch zu retten.", sourceObjectiveStatus = "unverified-source-field" }
quests[40071] = { id = 40071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod des Tierzähmers", description = "Solange ihr Tierzähmer am Leben ist, werden die Drogbar weiter ihre widerwärtigen Würmer großziehen.\n\nKorgrul ist dafür verantwortlich, aus den Nesthäkchen der Felskriecher riesige Monsterwürmer zu machen, auf denen sie in die Schlacht reiten.\n\nBegebt Euch in die Tiefen der Schlucht und tötet ihn, damit auch die Aufzucht dieser Monstrositäten ein Ende hat.", sourceObjective = "Tötet Zähmer Korgrul in der Felskriecherschlucht.", progress = "Bereitet Tierzähmer Korgrul ein Ende, damit auch die Ausbildung der Belagerungswürmer ein Ende findet.", completion = "Korgrul hat nichts anderes verdient. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40072] = { id = 40072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Die Aegis sichern", description = "Die Teufelsskorn mögen am Boden sein, aber der Kopf der Bestie regt sich noch. Der Gottkönig ist noch immer hinter der Aegis her und jemand muss ihn aufhalten.\n\nIhr habt schon so viele Prüfungen gemeistert... An dieser hier dürft Ihr nicht scheitern. Stellt die Aegis sicher, und wenn Ihr Skovald dazu jeden Knochen einzeln brechen müsst!\n\nDie Hallen der Tapferkeit erwarten Euch!", sourceObjective = "Besiegt den Gottkönig Skovald in den Hallen der Tapferkeit und sichert die Aegis von Aggramar.", completion = "Durch den Sieg über den Gottkönig gehört die Aegis von Aggramar jetzt Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[40073] = { id = 40073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pugg" }
quests[40074] = { id = 40074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Guk" }
quests[40075] = { id = 40075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rukdug" }
quests[40076] = { id = 40076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Start Demon Hunter Tracking Event" }
quests[40077] = { id = 40077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion beginnt", description = "Die Angriffstruppen unserer Dämonenjäger sind hier. Sie sind bereits im Gefecht gegen die Legion.\n\n{name}, hisst voller Stolz unsere Flagge und lasst sie sehen, mit wem sie es zu tun haben. Ich will die Furcht in ihren Augen sehen.", sourceObjective = "Tötet 15 Dämonen und tauscht das Banner der Legion aus, um den Grat der Verzweiflung einzunehmen.", completion = "Das können sie nicht ignorieren.\n\nLasst uns beginnen, den Rest unserer Truppen herbeizurufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40078] = { id = 40078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Bürde", description = "Nach Ashildirs Urteil ist Eure letzte Prüfung abgeschlossen.\n\nAber selbst die Hallen der Tapferkeit können warten, denn erst müssen wir etwas essen! Tot zu sein, macht ganz schön hungrig.\n\nKommt jetzt und bringt den Fisch mit zum Feuer. Der ist viel zu schwer, als dass ich ihn tragen könnte.", sourceObjective = "Nehmt den Fisch aus Havis Fischfass und steckt ihn auf den Speer über dem Feuer.", completion = "Eure Kochkünste werden wohl nur noch von Euren Kampffertigkeiten überboten.\n\nUnd jetzt, mit vollen Bäuchen, reiten wir nach Valhallas!", sourceObjectiveStatus = "unverified-source-field" }
quests[40079] = { id = 40079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Lyrath Moonfeather" }
