quests[40102] = { id = 40102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Murlocs: Die nächste Generation", description = "Jetzt ist es so weit! Murky und seine Anhänger benötigen einen geheimen Ort, an dem sie ohne Wissen der älteren Murlocs trainieren können, um zukünftig das Kommando zu übernehmen.\n\nEs gibt da eine schöne Höhle nicht weit von hier... Das Problem sind nur die vielen Makrura, die dort hausen.\n\nDie Höhle wäre eine gute Basis für die Kaulquappen. Murky wird ihnen zeigen, wo der Murloc die Locken hat!\n\nVerschmelzt Eure Gedanken mit denen von Murky in seinem Ei und zeigt ihm, wie es gemacht wird!", sourceObjective = "Verschmelzt Eure Gedanken mit denen von Murky und tötet 10 Höhlenmoosklacker.", progress = "Diese jungen Murlocs entwickeln sich prächtig. Sie werden diesem Küstenabschnitt gut tun.", completion = "Die Höhle wird eine hervorragende Basis für die jungen Kaulquappen sein!", sourceObjectiveStatus = "unverified-source-field" }
