quests[40111] = { id = 40111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtung der Bilgenflosseneindringlinge" }
quests[40112] = { id = 40112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Krieg - Malornes Liebling", description = "[In gebrochener Gemeinsprache] Shan'do nach Euch gefragt. Hat Eche'ro-Tier mit Nachricht am Geschirr geschickt.\n\nUnng Ak hört Geräusch, wie Eche'ro kämpft. Ihr sucht Tier? Ihm helfen, vielleicht gefiederter Nachtelf erleichtert.", sourceObjective = "Rettet Eche'ro.", completion = "<Eche'ro sieht kurz auf und senkt dann wieder den Kopf vor Euch. Das Tier ist Euch dankbar für die Hilfe.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40113] = { id = 40113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grrvrgull the Conquerer" }
quests[40120] = { id = 40120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unwürdiges Schicksal", description = "Ihr wisst es vielleicht nicht, aber Ihr steht hier auf dem ruhmreichen Boden von Morheim, der Heimat der größten Krieger unseres Landes. Unsere Taten waren herausragend und unser Heldenmut legendär. Es schmerzt mich, dass es so zu Ende gehen soll.\n\nDiese Kreaturen haben uns bei Einbruch der Nacht überrascht. Unsere Männer kämpften tapfer, aber wir waren zu stark in der Unterzahl. Jetzt verwesen ihre Leichen in der Sonne, und sie erhalten keine anständigen Begräbnisse oder Totenrituale.\n\nDas ist ein unwürdiges Ende für die glorreichen Krieger von Morheim. Wir wären Euch sehr dankbar, wenn Ihr in dieser Sache etwas unternehmen könntet.", sourceObjective = "Verwendet die qualmende Fackel, um die 8 verfallenden Kadaver in Morheim zu verbrennen.", progress = "Habt Ihr die Aufgabe erledigt?", completion = "Es ist gut zu wissen, dass unsere Krieger die gebührende Ehre erfahren haben.\n\nMögen sie jetzt ihre Siege in den Hallen von Valhallas feiern.", sourceObjectiveStatus = "unverified-source-field" }
quests[40121] = { id = 40121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leylinieneinfluss" }
quests[40122] = { id = 40122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cenarius, Hüter des Hains", description = "Ahh, Val'sharah.\n\nEs ist schon lange her, dass ich einen Fuß in diese heiligen Wälder gesetzt habe. Viel zu lange...\n\nUnsere Aufgabe hier ist einfach, {class}. Wir müssen meinen Mentor, Cenarius, rufen und herausfinden, wo er die Tränen von Elune verwahrt. Sie werden Euch unserem Ziel näherbringen, Sargeras' Grab zu versiegeln und die Legion aufzuhalten.\n\nAuf Euch warten schwere Prüfungen. Euer Aufenthalt hier ist lediglich eine Atempause von kurzer Dauer.\n\nKommt, das wird nicht viel Zeit in Anspruch nehmen.", sourceObjective = "Sprecht mit Malfurion Sturmgrimm in Lorlathil in Val'sharah.", completion = "So eine Verderbnis... habe ich noch nie zuvor erlebt.\n\nUnd trotzdem scheint sie irgendwie vertraut zu sein...", sourceObjectiveStatus = "unverified-source-field" }
quests[40123] = { id = 40123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Pakt der Nachtgeborenen", description = "<Thalyssra zuckt zusammen und hält sich ihren Bauch.>\n\nArgh... Ich kann diese Wunde nicht länger ignorieren.\n\nHelft mir, sie zu verbinden. Ich werde Euch alles erklären.", sourceObjective = "Legt Thalyssra einen Verband an.", completion = "Wir müssen einen Weg finden, Suramar zurückzuerobern.", sourceObjectiveStatus = "unverified-source-field" }
quests[40124] = { id = 40124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gift of the Storm Cooldown" }
quests[40125] = { id = 40125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ast des Arcan'dor", description = "Ihr habt den Zauberstein von Kel'danath benutzt, um zahllose Verdorrte zu besänftigen. Doch er enthält nur einen Bruchteil der Macht des Arcan'dor, die seiner schlummernden Saat entzogen wurde.\n\n<Thalyssra hält einen glänzenden, weißen Ast empor.>\n\nDer hier fiel aus dem Baum. Obwohl er abgetrennt wurde, ist er nicht tot. Unsichtbare Magiefäden halten die einzelnen Stücke des Arcan'dor zusammen.\n\nIch habe diesen Ast ein weiteres Mal mit Kel'danaths Bezauberung verzaubert. Damit könnt Ihr die arkane Essenz von noch mehr Verdorrten heilen. Setzt ihn weise ein.", sourceObjective = "Sprecht mit Thalyssra.", completion = "Ich hätte nie gedacht, dass ich einmal im Exil die Verdorrten studieren würde. Durch sie habe ich viel über mein eigenes Volk und die Art unserer Beziehung zum Nachtbrunnen gelernt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40126] = { id = 40126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Grelda" }
quests[40127] = { id = 40127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da-Nel's Quest" }
quests[40129] = { id = 40129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparatur der Kraftquelle", description = "<Ihr bemerkt etwas, das im Dreck glitzert. Nach kurzem Graben bergt Ihr den fast intakten Energiekern eines arkanen Konstrukts. Die Bruchstelle sieht sehr sauber aus. Vielleicht könnt Ihr ihn reparieren, wenn Ihr die anderen Bruchstücke findet.>", sourceObjective = "Ihr habt den leicht beschädigten Energiekern eines arkanen Konstrukts gefunden. Der Kern scheint reparabel zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40130] = { id = 40130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reingewaschen", description = "So mächtig die Legion auch sein mag, sie ist nicht die stärkste Kraft in Azeroth.\n\nEs gibt da einen Ort, an dem Verzauberin Ilanya und ich viele glückliche Stunden verbracht haben. Die Liebe, die einen solchen Ort durchdringt, ist stärker als Teufelsmagie, {name}.\n\nSucht den Quell von Nor'danil auf. Mit seinem Wasser kann man den Teufelstaub, den Ihr gesammelt habt, reinigen... und vielleicht auch mich läutern.\n\nIch treffe Euch dann dort.", sourceObjective = "Trefft Euch mit der gefallenen Priesterin am Quell von Nor'danil. Beobachtet, wie die Priesterin versucht, ein Läuterungsritual durchzuführen.", progress = "Es... Es hat funktioniert! Ich bin endlich wieder ich selbst!", completion = "Ich habe mich von dem Dämon befreit. Ich glaube, ich bin jetzt bereit zurückzukehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[40131] = { id = 40131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steinbalglederprobe", description = "Dieser Lederfetzen scheint Aufschluss über die Qualität der Bälge von Tieren auf den Verheerten Inseln zu geben.\n\nEuer Kürschnerlehrer in Dalaran hätte sicherlich Interesse daran.", sourceObjective = "Bringt die Steinbalglederprobe und 10 weitere Stücke Steinbalgleder zu Kondal Jägerschwur in Dalaran.", progress = "Wie kann ich Euch helfen?", completion = "Seid gegrüßt, {name}. Was habt Ihr mir heute mitgebracht?", sourceObjectiveStatus = "unverified-source-field" }
quests[40132] = { id = 40132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In einem Stück", description = "<Euer Lehrer schaut sich den Balg an.>\n\nDieser Balg lässt sich gut verwenden, aber leider ist er sehr klein. Ihr zollt dem Tier zu wenig Respekt, wenn Ihr es so zerhackt, {name}. Ihr macht zu wenig aus diesem Geschenk der Natur.\n\nZieht noch einmal los in die Wildnis. Zieht den Tieren unter uns die Häute in einem Stück ab und bringt sie mir dann.", sourceObjective = "Sammelt 20 unzerteilte Bälge, indem Ihr die Tiere der Verheerten Inseln fachgerecht häutet.", progress = "<Kondal erwartet Euch mit ernstem Gesichtsausdruck.>", completion = "Hm. Das ist besser.\n\nUnd denkt an meinen Ratschlag, wenn Ihr nächstes Mal das Kürschnermesser zückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40133] = { id = 40133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fetzen einer Hose", description = "Im Rachen dieses Tieres steckte ein Stück handgenähtes Tuch, auf dem das Wort \"singwa\" zu lesen ist.\n\n\"singwa\" ergibt zwar als Wort keinen Sinn, aber dafür ist es der Mittelteil des Nachnamens eines berühmten azerothischen Kürschners.", sourceObjective = "Bringt den Fetzen einer Hose zu Hemet Nesingwary am Hochberg.\n\nBereitgestellter Gegenstand:", completion = "Ihr habt meine Ersatzhose gefunden!", sourceObjectiveStatus = "unverified-source-field" }
quests[40134] = { id = 40134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hochbergbälge", description = "Ihr seid also auch <ein Kürschner/eine Kürschnerin>?\n\nDas freut mich, {name}! Hätte gar nicht gedacht, dass wir so viel gemeinsam haben.\n\nIhr MÜSST Euch einfach ein paar von den Bälgen anschauen, die es hier am Hochberg gibt. Ich würde mein Ersatzmonokel hergeben, um nur ein paar dieser edlen, seidigen Bälge in Händen halten zu können...", sourceObjective = "Verschafft Euch 5 Bärenbälge, 5 Urhornbälge und 5 Säblerbälge durch das Häuten von Tieren am Hochberg.", progress = "<Hemet blickt gierig in Richtung des Horizonts.>", completion = "Sind die etwa für mich, mein Junge? Ich... Ich weiß gar nicht, was ich sagen soll!\n\nHier, nehmt das. Das ist das Geringste, was ich tun kann.\n\n<Hemet steckt seine Nase tief in den Bärenbalg.>", sourceObjectiveStatus = "unverified-source-field" }
quests[40135] = { id = 40135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reisefreiheit", description = "Ich kann mich noch genau an früher erinnern, {name}. Ihr auch? So viel weniger Verantwortung... Ich konnte einfach herumreisen, wie es mir gefiel. Jetzt sitze ich hier am Hochberg mit meiner Jagdtruppe mehr oder weniger fest.\n\nUnd dabei gibt es noch so viele interessante Tiere in anderen Gegenden der Verheerten Inseln. Ich trage Euch die Orte in der Karte ein, damit Ihr losziehen und ein paar Bälge erbeuten könnt!", sourceObjective = "Erbeutet 5 Moschushirschbälge, 5 Löwenrobbenbälge, 5 Eberbälge und 5 Wolfsbälge.", progress = "Wenn Ihr fertig seid, zeige ich Euch ein paar Tricks.", completion = "Die sind ja wirklich wundervoll, {name}. Gut gemacht.\n\nIch kann Euch zeigen, wie Ihr beim Kürschnern noch bessere Resultate erzielt. Schaut Euch mal diesen Wolfsbalg an...", sourceObjectiveStatus = "unverified-source-field" }
quests[40136] = { id = 40136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloses Steinbalgleder", description = "Ihr seid jetzt schon eine ganze Weile <Kürschner/Kürschnerin>, aber so ein edles Leder habt Ihr noch nie gesehen. Widerstandsfähig, geschmeidig und von wundervoller Farbe...\n\nEuer Lehrer in Dalaran hätte daran sicherlich GROSSES Interesse.", sourceObjective = "Bringt das makellose Steinbalgleder zu Kondal Jägerschwur in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Da seid Ihr ja wieder, {name}. Was kann ich denn heute für Euch tun?", sourceObjectiveStatus = "unverified-source-field" }
quests[40137] = { id = 40137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leder für Ske'rit", description = "Dieser Balg beweist, dass Ihr alles über Leder gelernt habt, was ich Euch beibringen kann, {name}. Meine Fähigkeiten sind etwas eingeschlafen, seit ich hier sesshaft geworden bin.\n\nIch habe einen früheren Schüler, der Bälge aus den Tieren von Suramar gewinnt. Sein Name ist Ske'rit. Seine Fertigkeiten sind noch so scharf wie seine Klinge. Wenn Euch jemand noch etwas beibringen kann, dann er.", sourceObjective = "Meldet Euch bei Ske'rit in Suramar.", completion = "He, da. Ihr seid auch Kürschner?", sourceObjectiveStatus = "unverified-source-field" }
quests[40138] = { id = 40138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prüfung des Kreuzfahrers: Legendäre Bälge", description = "Ja, ich kann Euch was beibringen. Aber ich arbeite hier in Suramar immer noch an meinen Techniken. Vielleicht könnt Ihr mir sogar dabei helf'n.\n\nIch brauch zum Beispiel 'n paar ganz besond're Bälge. Ich brauche 'nen kräftigen weißen Yetipelz, 'ne sehr große Dämonenhaut und das dickste Terrorhornleder, das Ihr finden könnt.\n\nWenn Ihr das für mich besorgt, teile ich meine Ausbeute mit Euch und dem alten Kondal in der Stadt.", sourceObjective = "Erbeutet Eisheulers Balg aus der Prüfung des Kreuzfahrers.\n\nErbeutet Occu'thars Balg aus der Baradinfestung.\n\nErbeutet Horridons Balg vom Thron des Donners.", progress = "Na, Glück gehabt mit den Bälgen?", completion = "Ihr habt Euch ja selbst übertroffen. Schau sich einer diese Bälge an, Mann!", sourceObjectiveStatus = "unverified-source-field" }
quests[40139] = { id = 40139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Fenryrs Balg", description = "Wenn Ihr schon mal da seid, möcht' ich Euch um 'nen Gefallen bitten.\n\nIch hab' Gerüchte über 'nen großen, bösen Wolf gehört, der den Vrykul jede Menge Ärger macht. Sein Name soll Fenryr sein.\n\nIch will seinen Balg.", sourceObjective = "Erbeutet Fenryrs Balg, indem Ihr Fenryr in den Hallen der Tapferkeit häutet.", progress = "Fündig geworden? Lasst mal seh'n!", completion = "Ich hab ja schon 'ne Menge Wolfsbälge gesehen, aber der hier is' was ganz Besonderes.", sourceObjectiveStatus = "unverified-source-field" }
quests[40140] = { id = 40140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ske'rits Lederleitfaden", description = "Und damit is' meine Forschungsarbeit beendet.\n\n<Ske'rit übergibt Euch ein Schriftrollenbehältnis.>\n\nDaran hab' ich hier in Suramar gearbeitet. Bringt das zu Kondal, damit er das den ander'n Kürschnern beibringen kann.\n\nUnd weil Ihr mir so viel geholfen habt, steht da jetzt Euer Name drauf, {name}. Ich hoffe, das macht Euch nix aus.", sourceObjective = "Bringt Ske'rits Lederleitfaden zu Kondal Jägerschwur in Dalaran.", completion = "Ihr seid zurück und habt Ske'rits Buch dabei.\n\nLasst uns das mal zusammen anschauen, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[40141] = { id = 40141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmschuppenprobe", description = "Die Schuppe leuchtet vor elektrischer Energie auf.\n\nEuer Kürschnerlehrer in Dalaran hätte sicherlich Interesse daran.", sourceObjective = "Bringt die Sturmschuppenprobe zu Kondal Jägerschwur in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Ja, bitte, Kürschner?", sourceObjectiveStatus = "unverified-source-field" }
quests[40142] = { id = 40142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kern der Sturmschuppe", description = "Ah, ja. Die edle Sturmschuppe.\n\nIch habe ähnliche Schuppen in Nordend und einige am Himmelswall gesehen, aber diese Art Schuppen scheint hier ganz normal zu sein. Einer meiner Kollegen hat sich auf Kettenrüstungen spezialisiert und hätte sicher Interesse daran.\n\nUm diese Art Schuppen effizient zu nutzen, muss man zunächst einmal ihre Stärke verstehen. Achtet bei Eurer Beute auf zerbrochene, unverwendbare Schuppen und entfernt bei ihnen die Funken. Wenn Ihr erst die Funken gesehen habt, werdet Ihr die Sturmschuppe verstehen.", sourceObjective = "Besorgt 20 Sturmschuppenfunken, indem Ihr Tiere mit Schuppen auf den Verheerten Inseln häutet.", progress = "Habt Ihr diese Funken gesehen?", completion = "Sehr gut, {name}. Ein besseres Verständnis der Sturmschuppe führt zu besserer Kürschnerei und damit auch zu weniger unnötigen Toden von Tieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[40143] = { id = 40143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvollendete Abhandlung über die Eigenschaften von Sturmschuppen", description = "In den Falten dieses Balgs eingeklemmt findet Ihr ein Stück Papier. Es scheint sich um eine handgeschriebene Anleitung zum Kürschnern von Sturmschuppen zu handeln. Allerdings fehlen zu viele Teile des Manuskripts, um es verwenden zu können.\n\nVielleicht kann Euer Kürschnerlehrer in Dalaran Euch helfen, den Besitzer zu finden.", sourceObjective = "Bringt die unvollendete Abhandlung über die Eigenschaften von Sturmschuppen zu Kondal Jägerschwur in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "<Kondal schaut sich das Schriftwerk an und runzelt die Stirn.>\n\nIch kenne nur zwei Leute, die das geschrieben haben könnten, {name}. Und wenn Ihr es wünscht, kann ich Euch sagen, wo Ihr sie findet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40144] = { id = 40144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glielle", description = "Eine Kürschnerin hat sich in der Wildnis von Azsuna niedergelassen. Ihr Name ist Glielle und sie ist eine Nachtelfe... zumindest war sie das, als sie noch lebte.\n\nVielleicht gehörte die Schriftrolle ja ihr.", sourceObjective = "Sucht nach Glielle in Azsuna.", completion = "Was? Nein, diese Schriftrolle stammt nicht von mir. Ich schreibe dieser Tage nicht so viel.", sourceObjectiveStatus = "unverified-source-field" }
quests[40145] = { id = 40145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verborgen", description = "Ich kann Euch aber etwas beibringen.\n\nJeder kennt ja die auffälligen Sturmschuppen auf den Hintervierteln des Hippogryphen, aber wusstet Ihr, dass sie auch welche unter ihren Federn haben? Man muss nur wissen, wo man danach suchen muss.\n\n<Der Nachtelf deutet auf ein paar Stellen am Gelenk der Hippogryphenflügel.>\n\nUnd jetzt könnt Ihr losziehen und Euch Eure eigenen besorgen.", sourceObjective = "Besorgt 20 Hippogryphenschuppen.", progress = "Denkt daran, das ganze Tier zu untersuchen und nicht nur das, was oberflächlich sichtbar ist.", completion = "Ihr scheint Euch jetzt auszukennen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40146] = { id = 40146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hansi und Agnes", description = "Jetzt, wo Ihr mir diese Schriftrolle zeigt, fällt mir ein anderer Kürschner, beziehungsweise ein anderes Kürschnerpaar ein: mein Lehrling Hansi und seine Mutter Agnes.\n\nIch hörte zuletzt, dass sie in Sturmheim auf der Jagd nach Sturmdrachen seien.", sourceObjective = "Sucht nach Hansi in Sturmheim.", completion = "Ja, ja, ja, das ist mein Manuskript. Aber dafür ist jetzt keine Zeit.\n\nSchaut, was sie meiner MUTTER angetan haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[40147] = { id = 40147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mutters geliebtes Messer", description = "Vor Kurzem waren Mutter und ich auf dem Gipfel des nahe gelegenen Bergs, und sie wollte mir das Kürschnermesser zuwerfen, aber die Sicht war nicht so gut.\n\nIhr Messer ist immer noch irgendwo da oben. Ich würde mich schrecklich dabei fühlen, es einfach da zu lassen.", sourceObjective = "Beschafft Agnes' Kürschnermesser.", progress = "Mutter wollte immer lang genug leben, um mich noch sterben zu sehen. Warum musste das geschehen!?", completion = "Das ist es. Da, da sind noch Teile von mir dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[40148] = { id = 40148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siedend heiße Rache", description = "Er kam wie aus dem Nichts. Ich wartete darauf, dass meine Mutter mit dem Häuten ihrer Hälfte des Drachen fertig würde, als der größte Sturmschwingendrache angerast kam, den ich je gesehen habe und... und...\n\n<Hansi findet seine Fassung wieder.>\n\nIch möchte, dass Ihr so viele von ihnen tötet wie möglich. Ob Ihr sie häutet oder nicht, ist mir egal. Nehmt einfach Rache für meine Mutter!", sourceObjective = "Tötet 15 ausgewachsene Sturmjäger.", completion = "Ich danke Euch. Ich weiß auch nicht warum, aber dank Eures Massakers an ihnen fühle ich mich etwas besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[40149] = { id = 40149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakol'nir muss sterben", description = "Der Drache, der meine Mutter getötet hat, wird Drakol'nir genannt.\n\nMutter wollte immer seine Schuppen als Anhänger tragen. Aber wir hatten nie die Gelegenheit, ihn zu häuten, weil ich ihn nicht allein töten konnte und Mutter sich nicht viel aus der Jagd gemacht hat.\n\nIhr... Ihr könntet meiner Mutter doch vielleicht eine bringen?", sourceObjective = "Beschafft eine Schuppe von Drakol'nir.", progress = "Selbst WENN es mir gelungen wäre, Drakol'nir zu töten, hätte ich ihn niemals hier herunterschaffen können.", completion = "<Hansi legt die Schuppe seiner Mutter liebevoll auf die Brust. Selbst im Tod scheint sie missbilligend zu sein.>\n\nIch danke Euch, {name}. Hier, Ihr könnt ihr Kürschnermesser haben. Es ist nichts Besonderes, aber sie braucht es ja auch nicht mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[40151] = { id = 40151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makellose Sturmschuppe", description = "Ihr seid jetzt schon eine ganze Weile <Kürschner/Kürschnerin>, aber so eine edle Schuppe habt Ihr noch nie gesehen.\n\nEuer Lehrer in Dalaran hätte daran sicherlich GROSSES Interesse.", sourceObjective = "Bringt die makellose Sturmschuppe zu Kondal Jägerschwur in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Was habt Ihr denn da, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[40152] = { id = 40152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppen für Ske'rit", description = "Eure Fähigkeiten übertreffen meine bereits, {name}. So eine edle Schuppe habe ich noch nie gesehen. Und dann wurde sie auch noch waidmännisch perfekt entfernt.\n\nWenn Ihr noch mehr lernen wollt, müsst Ihr Euch an einen noch erfahreneren Kürschner als mich wenden. Sein Name ist Ske'rit und er war einst mein Schüler.\n\nIhr findet ihn in den wilden Gebieten von Suramar.", sourceObjective = "Sucht Ske'rit in Suramar auf.", completion = "Was haben wir denn da?", sourceObjectiveStatus = "unverified-source-field" }
quests[40153] = { id = 40153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Karazhan: Legendäre Schuppen", description = "Ich kenne mich ganz gut mit Schuppen aus, aber so langsam verlern' ich mein Handwerk wieder, weil ich dauernd nur mit Sturmschuppen arbeite. Hab schon ganz vergessen, wie die andern aussehen.\n\nIch brauche 'n paar spezielle Schuppen zum Vergleich: 'ne Schuppe von 'nem Netherdrachen, 'ne schöne heiß-schwarze Drachenschuppe und das dickste Stück Chitin, das Ihr auftreiben könnt.\n\nIch muss mal was anderes in der Hand halten als nur Sturmschuppen.", sourceObjective = "Besorgt die Schuppe von Nethergroll aus Karazhan, die Schuppe von Sartharion aus dem Obsidiansanktum und die Schuppe von Garalon aus dem Herz der Angst.", progress = "Hat ja 'ne ganze Weile gedauert. Habt Ihr die Schuppen?", completion = "Gut gemacht, Kürschner.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40154] = { id = 40154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Die Schuppen von Serpentrix", description = "Ich muss Euch um 'nen kleinen Gefallen bitten.\n\nIch war schon 'ne Weile nicht mehr in Azsuna und hier aus Suramar komm' ich auch nich' so schnell weg. Das Problem ist: Da draußen wartet 'ne große, alte Schlange nur darauf, gehäutet zu werden.", sourceObjective = "Besorgt die Schuppen von Serpentrix, indem Ihr Serpentrix im Dungeon \"Azsharas Zorn\" häutet.", progress = "Zeigt mal her, Kürschner.", completion = "Saubere Arbeit. Ihr könnt gut mit dem Messer umgeh'n, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40155] = { id = 40155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ske'rits Notizen zur Schuppenkürschnerei", description = "Jetzt wo ich alle Schuppen beisammen hab', weiß ich alles, was ich wissen muss.\n\n<Ske'rit überreicht Euch ein paar handgeschriebene Notizen.>\n\nHier sind meine neuesten Erkenntnisse über Sturmschuppen. Bringt sie Kondal und lest sie zusammen durch.", sourceObjective = "Bringt Ske'rits Notizen zur Schuppenkürschnerei zu Kondal Jägerschwur in Dalaran.", completion = "Ihr habt mit Ske'rit zusammengearbeitet? Das hätte ich mir denken können. Ihr beide passt gut zusammen.\n\nLasst mal sehen, was er geschrieben hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[40156] = { id = 40156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsbalgprobe", description = "Dieser dämonische Balg ist vollkommen anders als alle anderen Tierhäute, die Ihr bis jetzt kennengelernt habt.\n\nEuer Kürschnerlehrer in Dalaran hätte sicherlich Interesse daran.", sourceObjective = "Bringt die Teufelsbalgprobe zu Kondal Jägerschwur in Dalaran.\n\nBereitgestellter Gegenstand:", completion = "Ich kenne mich nicht sonderlich gut mit dämonischen Bälgen aus, {name}. Ich möchte lieber nichts damit zu tun haben.\n\nAber ich werde Euch erzählen, was ich darüber weiß...", sourceObjectiveStatus = "unverified-source-field" }
quests[40157] = { id = 40157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine unziemliche Aufgabe", description = "Ich bin beeindruckt davon, was Ihr hier alles abhäuten konntet, vor allem Teufelsbalg.\n\nMein Wissen auf diesem Gebiet ist zwar begrenzt, aber ich kenne jemanden, der seine Kürschnereikünste womöglich an solchen Bestien geschult hat.\n\nIhr könnt meinen früheren Lehrling Ske'rit in Suramar finden. Fragt ihn, ob er weiß, wie man beim Kürschnern von Dämonen bessere Ergebnisse erzielt.", sourceObjective = "Sucht Ske'rit in Suramar auf.", completion = "Was wollt Ihr denn, Mann?", sourceObjectiveStatus = "unverified-source-field" }
quests[40158] = { id = 40158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Dämonen das Fell gerben", description = "Oh ja, ich hab schon 'ne Menge Dämonen geseh'n, seit ich hier bin. Und es ist gar nicht so einfach, die zu häut'n.\n\nIhre Haut ist zäher als die von normalen Tieren, faserig, seht Ihr? Aber wenn Ihr so viel wie möglich aus ihren Häuten heraushol'n wollt, dann müsst Ihr mehr üb'n.\n\nIch hab gehört, im Finsterherzdickicht gibt's eine Kreatur mit Haut so zäh wie die von einem Dämon. Wenn Ihr sie häut'n geht, versucht, gleichmäßig mit dem Strich zu schneid'n.\n\nBringt mir die Haut, um mir zu zeig'n, dass Ihr versteht, was ich Euch erkläre.", sourceObjective = "Geht ins Finsterherzdickicht und tötet Dresaron. Häutet ihn und bringt seine Haut zu Ske'rit in Suramar.", progress = "Schon Glück dabei gehabt, die Haut zu besorg'n?", completion = "<Ske'rit nimmt Euch die Haut ab und betrachtet sie.>\n\nMann, Ihr habt so langsam den Bog'n raus.", sourceObjectiveStatus = "unverified-source-field" }
quests[40159] = { id = 40159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Der modrige Balg von Nythendra", description = "Nun gilt es nur noch einen Dämonenbalg einzusammeln... aber er gehört keinem Dämon. Es ist ein Großdrache.\n\nNythendra, der große grüne Großdrache, wurde fast vollständig vom Alptraum verschlungen. Nur ein wahrer Kürschnereimeister könnte die letzten Reste des von Insekten zerfressenen Balgs vom Kadaver entfernen.\n\nViel Glück, {name}. Zeigt mir, was Ihr gelernt habt.", sourceObjective = "Besorgt Euch den modrigen Balg von Nythendra.", progress = "Glück mit dem Großdrachen gehabt?", completion = "Ihr habt es geschafft, {name}. Damit habt Ihr Euch all mein Wissen verdient.\n\nUnd nun ab mich Euch und zieht der Welt das Fell über die Ohren!", sourceObjectiveStatus = "unverified-source-field" }
quests[40160] = { id = 40160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magische Muscheln", description = "<Die Muschel vibriert vor arkaner Energie.>\n\nWas haben die Murlocs mit magischen Muscheln vor?\n\nVielleicht können Eure nachtsüchtigen Verbündeten etwas damit anfangen.", sourceObjective = "Sammelt energiegeladene Muscheln von den Sehergratmurlocs am Riff der Murlocs ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40161] = { id = 40161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie aus dem Untergrund", description = "Habt Ihr sie gesehen, {name}?\n\nDas sind keine gewöhnlichen Murlocs. Sie wurden von der Leylinie, die von Azsuna in dieses Land führt, hierhergelockt.\n\nIrgendwie ist es ihnen gelungen, die arkane Energie anzuzapfen und diese Kräfte für ihre eigenen, unseligen Zwecke zu missbrauchen.\n\nWir müssen diese Eingriffe aufhalten, um die Leylinie intakt zu halten.", sourceObjective = "Zerstört die Sehergratleitungen am Riff der Murlocs.", sourceObjectiveStatus = "unverified-source-field" }
quests[40164] = { id = 40164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[40166] = { id = 40166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Leybad nehmen", description = "Ich habe beobachtet, wie diese Sehergratmurlocs kleinere Elementare heraufbeschworen haben. Das ist eine beachtliche Leistung für Murlocs. Aber ihr Hochbeschwörer, Blargrrrl, versucht jetzt, Torrentus aus dem Fluss heraufzubeschwören.\n\nIch bezweifle, dass ein einfacher Murloc die Macht hat, ein solch mächtiges Wesen wie Torrentus zu beherrschen.\n\nBlargrrrl wird in tiefe Trance verfallen sein, wenn er das tatsächlich versuchen sollte. Wir benötigen ein mächtiges Mittel, um diesem Ritual Einhalt zu gebieten.\n\nBadet selbst in Leyenergie und kehrt dann zu mir zurück.", sourceObjective = "Badet in Leyenergie am Riffs der Murlocs.", sourceObjectiveStatus = "unverified-source-field" }
quests[40167] = { id = 40167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hulns Geschichte", description = "Ihr arbeitet daran, die Stämme zu vereinen. Das ist eine beachtliche Leistung. In der Geschichte dieses Berges ist das zuvor nur einmal vorgekommen.\n\nHuln Hochberg hat vor Tausenden von Jahren die Stämme vereint, um die Legion im Krieg der Ahnen zu bekämpfen.", sourceObjective = "Sprecht mit Geistwandler Ebenhorn, um mehr über Huln Hochberg zu erfahren.", progress = "Die Geschichte dieses Ortes geht weit über unser eingeschränktes Erinnerungsvermögen hinaus.", completion = "Ihr habt nur einen Ausschnitt dessen gesehen, was Huln Hochberg zu seinen Lebzeiten erreicht hat. Lasst uns noch etwas tiefer in die Vergangenheit zurückblicken...", sourceObjectiveStatus = "unverified-source-field" }
quests[40168] = { id = 40168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wirbelnde Phiole", description = "Als Ihr die Phiole berührt, wird Euer Verstand von Erinnerungen durchflutet, die zum Teil gar nicht Eure eigenen sind. Am deutlichsten könnt Ihr Euch daran erinnern, wie Ihr eine ähnliche Phiole mit jemandem in Shattrath austauscht, während A'dals Licht hinter Euch aufleuchtet. So sehr Ihr es auch versucht, es will Euch einfach nicht einfallen, wann das gewesen sein könnte. Aber vielleicht liegt diese Begebenheit ja auch in der Zukunft?", sourceObjective = "Bringt die wirbelnde zeitverzerrte Phiole zur zentralen Kuppel in Shattrath.", completion = "Oh, wie interessant!\n\n<Cupri schnappt sich die Phiole und untersucht sie eingehend.>\n\nVielleicht hatte Zeph doch recht, uns hier weitersuchen zu lassen. Diese Phiole stammt definitiv aus keiner derzeit bekannten Zeitlinie. Das ist wirklich ungewöhnlich! Danke, dass Ihr sie mir gebracht habt. Oder habt Ihr sie mir bereits zuvor schon einmal gebracht...?", sourceObjectiveStatus = "unverified-source-field" }
quests[40169] = { id = 40169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An der Wegkreuzung", description = "Eine frühere Schülerin von mir hat uns während des Kriegs verlassen, kurz bevor wir alle verflucht wurden.\n\nIch habe vor Kurzem gehört, dass sie in der Nähe des Teufelsfeuervorstoßes gesehen wurde. Ich würde sehr gern noch einmal mit ihr sprechen.\n\nGeht und sucht nach ihr. Bringt ihr das Tagebuch und lasst sie wissen, dass ich ihr keine Vorwürfe mache.\n\nUnd wenn sie einverstanden ist, könnt Ihr sie gerne zu mir zurückbringen.", sourceObjective = "Sucht nach Hinweisen auf die Priesterin in der Nähe des Teufelsfeuervorstoßes.\n\nBereitgestellter Gegenstand:", completion = "<Der Satyr nimmt das angebotene Tagebuch entgegen und schluchzt.>\n\nDas Buch gehört jemanden, der schon lange verschwunden ist, Fremder. Ihr solltet mich lieber in Ruhe lassen an diesem von Teufelsmagie verseuchten Ort.", sourceObjectiveStatus = "unverified-source-field" }
quests[40170] = { id = 40170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stunde der Amateure", description = "Die Jagdhütte hat eine Menge Amateure angelockt, die sich als echte Jäger ausgeben. Mit ihren Mätzchen vertreiben die uns die ganzen Beutetiere!\n\nIch bin zwar ein Meister am Gewehr, aber in Verhandlungsfragen bin ich nicht ganz so bewandert.\n\nTut uns doch einen Gefallen und sagt diesen Anfängerjägern, dass sie sich verziehen sollen, ja?", sourceObjective = "Konfrontiert die Amateurjäger im Kieferfelsbecken.", completion = "Ihr scheint Talent im Umgang mit Amateuren zu haben. Vielleicht könnt Ihr meiner Ghostwriterin Addie helfen?\n\nIch habe versprochen, ihr das Jagen beizubringen, aber ich habe keine Zeit, ihr die Grundlagen zu erklären.", sourceObjectiveStatus = "unverified-source-field" }
quests[40173] = { id = 40173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das instabile Prisma", description = "Das Prisma scheint sich nicht in einem einzelnen Zeitstrom stabilisieren zu können, wodurch es eine schattenhafte Kälte verströmt, wie Ihr sie seit Nordend nicht mehr gespürt habt. Für einen Magier aus Dalaran wäre dieses Relikt sicher von höchstem Interesse.", sourceObjective = "Bringt das kalte zeitverzerrte Prisma zu einem interessierten Magier in Dalaran.", completion = "Lasst mich mal sehen.\n\n<Auzin studiert das Prima und wendet sich dann wieder Euch zu.>\n\nHm... Cupri könnte bestimmt tausend verschiedene Tests an diesem Ding durchführen. Damit erhärtet sich unser Verdacht, dass jemand Drittes damit herumexperimentiert hat... oder jemand Sechstes...\n\nDarf ich es behalten?", sourceObjectiveStatus = "unverified-source-field" }
quests[40175] = { id = 40175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sleeping Bear" }
quests[40176] = { id = 40176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Kopf bis Fuß", description = "Ihr wart fleißig, {name}. Und wie ich sehe, habt Ihr ein paar neue Muster entworfen.\n\nSollen wir noch eins hinzufügen?", sourceObjective = "Stellt ein Paar robuste Steinbalgstiefel her.\n\nDazu werdet Ihr Namhas Gerbrahmen und Namhas Werkbank im Legendäre Leder verwenden müssen.", progress = "Ich bin sehr gespannt, was dabei rauskommt.", completion = "Es fasziniert mich immer noch, wie mühelos man dieses Leder in Form bringen kann. Es ist so geschmeidig und doch so stark.\n\nIch glaube, Ihr könnt jetzt mithilfe meines Musters Eure eigenen Stiefel herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40177] = { id = 40177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lederlady", description = "Ich möchte, dass Ihr von jetzt an mit meinen Lehrlingen zusammenarbeitet.\n\nDie erste ist Diana Kanning. Sie hat sich auf weiche Lederrüstungen spezialisiert und legt nicht so viel Wert auf Kettenrüstungen wie die Zwillinge.\n\nSucht sie auf und sprecht mit ihr über diese neue Art Leder.", sourceObjective = "Trefft Euch mit Diana Kanning.", completion = "Mit Euch hat Namha also gesprochen. Freut mich, Euch kennenzulernen.\n\nIch hoffe, wir können neben Eurem Helm noch weitere Muster in die Liste aufnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40178] = { id = 40178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Voll vor die Brust", description = "Alle Vrykul in Nordend haben starke Rüstungen getragen, aber die ihrer Handwerker waren die stärksten.\n\nBegebt Euch nach Sturmheim und findet jemanden, der sich mit Lederrüstungen auskennt. Bringt mir dann seine Brustrüstung.", sourceObjective = "Besorgt das Gewand des Balgformers.", progress = "Wie läuft die Suche?", completion = "<Diane schaut sich die Brustrüstung eingehend an.>\n\nDas ist eine sehr interessante Bauart. Ich glaube, davon können wir relativ leicht eine Nachbildung anfertigen.\n\nHier, versucht es mal mit diesem Muster.", sourceObjectiveStatus = "unverified-source-field" }
quests[40179] = { id = 40179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmheimmassaker", description = "Da unten gibt es ein Land namens Sturmheim, in dem diese Vrykul leben. Ich erinnere mich noch an sie aus meinen Tagen in Nordend.\n\nUnd am deutlichsten erinnere ich mich an ihre gut verarbeiteten Rüstungen.\n\nWenn die hiesigen Vrykul auch so geschickt sind wie die in Nordend, dann können wir sicher noch etwas von ihren Rüstungen lernen.", sourceObjective = "Besorgt 7 Lederbindungen der Vrykul.", progress = "Gibt es Schwierigkeiten mit den Vrykul?", completion = "Ja, da habt Ihr mir eine schöne Auswahl an Ausrüstung mitgebracht. Mal sehen, was wir hier haben...\n\n<Diane sieht sich die Rüstungsteile eine Weile lang sehr sorgfältig an.>\n\nSchaut mal, {name}. Hier haben sie das Leder durch das Überstechen der Nähte gefestigt...", sourceObjectiveStatus = "unverified-source-field" }
quests[40180] = { id = 40180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindende Geschäfte", description = "Die zwei Zwerge hinter mir sind die Gebrüder Leuchtegold. Sie sind meine hiesigen Experten auf dem Gebiet der Kettenrüstungen.\n\nRanid ist vor allem am Profit interessiert, während sein Bruder Thanid mehr Wert auf die praktische Arbeit legt.\n\nStellt Euch bei Thanid vor. Vielleicht wollt Ihr ja eine Weile mit ihm zusammenarbeiten, um zu erfahren, wie wir aus diesen Sturmschuppen etwas ganz Besonderes machen können.", sourceObjective = "Trefft Euch mit Thanid Leuchtegold.", completion = "Schön, dass Ihr da seid! Ihr müsstet nämlich etwas ganz Wichtiges für mich erledigen.\n\nHört nicht auf das, was mein Bruder sagt. Er ist schon seit vielen Jahren aus der Übung, aber er glaubt immer noch, er sei besser als ich.\n\nDas ist vollkommener Unsinn, mein Lieber.", sourceObjectiveStatus = "unverified-source-field" }
quests[40181] = { id = 40181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehrräuber", description = "Ich habe von einem riesigen Schloss in Val'sharah gehört, in dem eine große Armee einquartiert ist. Die Rüstungen dieser Soldaten werden sicher nicht aus Stroh und Stöckchen bestehen.\n\nIch wette, sie haben bereits eine Reihe Kettenrüstungen für die Truppen gefertigt, die nur darauf warten, abhandenzukommen.\n\nWir sollten dort mal vorbeischauen und sehen, was wir uns aus ihrer Waffenkammer \"borgen\" können.", sourceObjective = "Beschafft 5 Teile der Rabenwehrrüstung.", progress = "Lasst Euch nur nicht gefangen nehmen, mein Lieber.", completion = "Ich wusste, dass Ihr das hinbekommt! Gute Arbeit, mein Lieber.\n\n<Thanid schaut sich die Stücke aufmerksam an.>\n\nSehr clever. Die Elfen verstehen etwas von ihrem Handwerk.\n\nDiese Bauart zu kopieren, sollte aber kein Problem darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40182] = { id = 40182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die muss mit", description = "Zwar sind alle Arten Rüstungsteile der Rabenwehr spektakulär, am meisten aber interessieren mich ihre Brustrüstungsteile.\n\nVielleicht könnt Ihr jemanden Bedeutendes unter ihnen finden und ihm sein Kettenhemd abnehmen.\n\nUnd falls es Euch dann leichter fällt: Ich hab gehört, dass die alle verflucht sind. Ihr tut ihnen wahrscheinlich noch einen Gefallen.", sourceObjective = "Beschafft eine Rabenwehrhalsberge.", progress = "Ich sag ja immer: Brustrüstung dabei, auf sie mit Geschrei!", completion = "Oh, die ist wirklich wundervoll. Schaut Euch nur diese fantastische Arbeit an.\n\n<Thanid sieht sich das Stück sehr sorgfältig an.>\n\nUnd so wie sie gebaut ist, sollte man sie auch ganz leicht nachbauen können.\n\nHier, mein Lieber, versucht es mal mit diesem Muster.", sourceObjectiveStatus = "unverified-source-field" }
quests[40183] = { id = 40183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf den Schädel", description = "Also gut, {name}. Ich möchte, dass Ihr mir bei der Herstellung eines Helms helft.\n\nZunächst müssen wir die Bälge enthaaren, dann gerben und dann in verwendbare Stücke zuschneiden.\n\nFolgt meinem Beispiel.", sourceObjective = "Stellt eine grobe Kriegsbalgmaske her.\n\nDazu werdet Ihr Namhas Gerbrahmen und Namhas Werkbank im Legendäre Leder verwenden müssen.", progress = "So langsam glaube ich, dass wir ein gutes Team abgeben.", completion = "Gut gemacht, {name}. Hier ist eine Abschrift des Musters für Eure Sammlung.\n\nIch selbst arbeite lieber mit weicher Lederrüstung. Wenn Ihr einen KETTENhelm wollt, müsst Ihr mit Ranid sprechen... Aber das wird wohl nicht ganz billig für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[40184] = { id = 40184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taurengerbung", description = "Habt Ihr von den Stämmen der Hochbergtauren gehört? Sie sind den Tauren auf Kalimdor durchaus ähnlich.\n\nUnd ich hörte, dass unter ihnen ein Lederverarbeitungsmeister ist, der uns vielleicht mit ein paar neuen Mustern weiterhelfen kann.\n\nReist zum Hochberg und findet heraus, ob sie bereit sind, Euch etwas über ihre Rüstungsherstellung zu verraten.", sourceObjective = "Meldet Euch bei Hrul Scharfhuf.", completion = "Ich kann das Leder an Euch riechen, Fremder.\n\nEs ist in Eurer Haut, in Euren Knochen und in Eurem Geist. Und genauso deutlich ist es, dass Ihr etwas über die Lederverarbeitung in diesem Land lernen wollt.\n\nWenn dies der Fall ist, muss ich Euch zunächst auf die Probe stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40185] = { id = 40185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Bürde", description = "In einer der letzten Schlachten ist mein Bruder Lohrumn ums Leben gekommen. Ein Drogbar hat dann seine Rüstung gestohlen.\n\nIhr würdet ihm große Ehre erweisen, wenn Ihr die Rüstung zurückholen könntet. Ich werde Euch auch gut dafür bezahlen, <Lederverarbeiter/Lederverarbeiterin>.", sourceObjective = "Besorgt Lohrumns Schulterschutz.", progress = "Die Rüstung meines Bruders... Habt Ihr sie gefunden?", completion = "Ich danke Euch, {name}. Wie versprochen werde ich Euch unser Handwerk lehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[40186] = { id = 40186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Drogbar Druck machen", description = "Wir führen zurzeit Krieg gegen ein Volk, das wir die Drogbar nennen. Wir haben lange in Frieden mit den Drogbar gelebt, aber in letzter Zeit respektieren sie nichts und niemanden außer sich selbst.\n\nTötet sie. Beweist Euren Wert als <Verbündeter/Verbündete> der Tauren. Wenn Euch das gelingt, werde ich mein Wissen mit Euch teilen.", sourceObjective = "Tötet 15 Drogbar, um Hrul Eure Loyalität zu beweisen.", completion = "Wenn Ihr die Drogbar niederstrecken könnt, dann seid Ihr vielleicht meines Wissens würdig.\n\nIch werde Euch für den Anfang einige einfache Muster an die Hand geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[40187] = { id = 40187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kettenglieder", description = "Nun <mein Junge/meine Liebe>, ich fürchte, mein Wissen, was diese Schuppen anbetrifft, hat sich erschöpft. Ich weiß wirklich nicht, wie ich die übrigen Teile für einen kompletten Satz herstellen soll.\n\nMir ist zu Ohren gekommen, dass es in den Städten der Elfen von Azsuna einige großartige Handwerker gibt. Vielleicht gibt es den einen oder anderen noch.\n\nGeht und sucht einen Meister. Vielleicht bekommen wir von ihm die fehlenden Muster.", sourceObjective = "Findet einen Meister der Lederverarbeitung in Azsuna.", completion = "Ja, {class}? Ihr möchtet wissen, wie man elfische Kettenrüstungen herstellt?\n\nIch verstehe. Vielleicht können wir einen Handel abschließen, der uns beiden zugutekommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[40188] = { id = 40188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kalt serviert", description = "Mein Partner und ich wurden beide Opfer der Folgen der Zerschlagung. Wir wurden von einem Freund, dem wir vertrauten, betrogen und im Stich gelassen.\n\nDieser \"Freund\" ist vor Kurzem in den Ruinen im Osten von hier aufgetaucht. Sein Name ist Ranaris.\n\nGeht und rächt uns, und ich werde Euch mit einem Teil meiner Weisheit belohnen.", sourceObjective = "Tötet Ranaris in den Untiefen von El'dranil.", completion = "Ihr seid ein Mann, der zu seinem Wort steht, {name}. Ich danke Euch für die Dienste, die Ihr uns erwiesen habt.\n\nWie vereinbart werde ich Euch nun an meiner Weisheit teilhaben lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40189] = { id = 40189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagafachwissen", description = "Die Naga dieser Gegend tragen nur wenig Rüstung, aber was sie tragen, ist besonders haltbar.\n\nWenn Ihr ein stärkeres Schulterteil herstellen wollt, würde ich mir zunächst die Rüstung der Naga anschauen und dann ein Muster von ähnlicher Herstellungsweise fertigen.\n\nDie Stadt in der Nähe ist von Naga überschwemmt. Tötet sie und bringt mir ihre Rüstung, dann zeige ich Euch, was ich meine.", sourceObjective = "Besorgt 7 Nagaschulterschutze.", progress = "Auch wenn sie widerlich sind, so beherrschen sie ihre Handwerkskunst doch immer noch so gut wie jeder andere Meister.", completion = "Das sind schöne Stücke. Seht hier...\n\n<Celea erklärt Euch die Herstellungsweise der Rüstung.>\n\nUnd nun, denke ich, könnt Ihr etwas Gleichwertiges herstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40190] = { id = 40190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Härten der Häute", description = "Ihr müsst zurück zum Hochberg, {name}. Mir ist zu Ohren gekommen, dass man dort noch effizientere Möglichkeiten für die Herstellung unserer Muster kennt.\n\nWenn Ihr dort eintrefft, legt ein gutes Wort für mich ein, ja? Ich würde gerne eine Beziehung mit den Tauren aufbauen, damit ich Euch nicht ständig hin und her schicken muss.", sourceObjective = "Kehrt zum Hochberg zurück und sprecht mit Hrul Scharfhuf.", completion = "Ihr möchtet noch mehr lernen, {name}?\n\nAlso schön, fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[40191] = { id = 40191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschichten der Gerbung", description = "Auf dem Leder auf den Gerbrahmen hinter mir sind die uralten Methoden der Lederverarbeiter unseres Stammes verzeichnet.\n\nSie erzählen die Geschichten der Meister, die durch ihre Beharrlichkeit... und manchmal auch durch Glück... unsere Lederverarbeitung weiterentwickelt haben.\n\nLest die Geschichten und lernt daraus. Vielleicht findet Ihr Hinweise, wie Ihr Eure eigenen Methoden verfeinern könnt.", sourceObjective = "Lernt aus den Geschichten, die Ihr auf den einzelnen Gerbgestellen findet.", completion = "Ich sehe Hoffnung in Euren Augen, {name}. Ich nehme an, dass unsere Erfahrungen aus der Vergangenheit Euch in Eurer Zukunft helfen werden?", sourceObjectiveStatus = "unverified-source-field" }
quests[40192] = { id = 40192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klauen des Lands", description = "Aufgrund meiner persönlichen Erfahrungen bevorzuge ich stärkere Materialien für meine Rüstungsteile. Sie halten länger und man braucht nicht so viele davon.\n\nIch verwende zum Beispiel die Klauen von Kieferfelspirschern. Wenn Ihr mir ein paar davon holt, kann ich Euch vielleicht zeigen, wie bessere Materialien zu mehr Effizienz führen.", sourceObjective = "Besorgt 100 Pirscherklauen.", progress = "Ihre Klauen gehören zu den stärksten, die ich je gesehen habe.", completion = "Ihr habt so viele gesammelt, dass ich viele Monde damit auskommen werde.\n\n<Hrul beginnt seine Arbeit mit den Klauen. Es ist offensichtlich, dass er nur sehr wenig von allem benutzt, aber dennoch ein ausgezeichnetes Rüstungsteil herstellt.>\n\nIch hoffe, Ihr konntet hieraus etwas lernen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40193] = { id = 40193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kleine Fehler ausbügeln", description = "Hört gut zu, <mein Junge/meine Liebe>. Alles, was man herstellt, kann immer noch besser gemacht werden. Ich habe nur noch nicht ganz herausgefunden, wie das mit diesen schicken neuen Schuppen genau geht.\n\nVielleicht kann uns Eure geisterhafte Elfenfreundin helfen. Wenn sie TATSÄCHLICH etwas weiß, wäre es sehr nett, wenn Ihr mir diese Information zukommen lassen könntet.\n\nDas würde auf jeden Fall diesen Laden lukrativer machen.", sourceObjective = "Kehrt zu Celea in Azsuna zurück.", completion = "Ihr seid aber schnell wieder da, {name}.\n\nAh, Ihr möchtet die Herstellung Eurer bereits bekannten Muster meistern. Das zeichnet einen wahren Meister der Lederverarbeitung aus.\n\nJa, ich kann Euch helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40194] = { id = 40194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgewonnene Fracht", description = "Das Schiff, auf dem sich auch mein Bruder befand, hatte außergewöhnlicher Kettenrüstungen als Fracht an Bord. Wie ich die Riesen kenne, hatten sie wahrscheinlich keine Verwendung für sie und lassen sie in ihren Höhlen wild verstreut herumliegen.\n\nWenn Ihr diese Rüstungen bergen und sie hierherbringen könntet, kann ich Euch die Techniken erklären, wie man sie herstellt. Das sollte Euch eine klare Vorstellung davon geben, wie Ihr Eure Arbeitsabläufe verbessern könnt.", sourceObjective = "Besorgt 5 Kettenrüstungslieferungen.", progress = "Habt ihr etwas von der Fracht retten können?", completion = "Sie sind ein wenig rostig, aber wenigstens sind sie nicht beschädigt. Lasst mich erklären, wie sie hergestellt wurden...\n\n<Celea beginnt, die Abläufe zu beschreiben, wie die Rüstung hergestellt wurde.>\n\nLangwierig, aber effizient.", sourceObjectiveStatus = "unverified-source-field" }
quests[40195] = { id = 40195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wagemutige Rettung", description = "Mein Bruder, Taldranis, befand sich auf einem Schiff, das hierher nach Azsuna unterwegs war. Das Schiff geriet in einen Hinterhalt der Meeresriesen, und mein Bruder wurde gefangen genommen.\n\nIch glaube, dass er immer noch sein Dasein in diesen furchtbaren Höhlen fristet und Sklavenarbeit für die Riesen leisten muss. Bitte geht und befreit ihn.\n\nNehmt das hier mit, es wird ihn vielleicht ausreichend schützen, falls Ihr in Schwierigkeiten geraten solltet. Und seid vorsichtig, damit die Riesen Euch nicht auch noch gefangen nehmen.", sourceObjective = "Sucht nach Taldranis in Ozeanus' Bucht und bringt ihm die Rüstung.", completion = "Moment, Celea hat Euch geschickt? Ich dachte, sie wäre seit Ewigkeiten verschollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40196] = { id = 40196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abenteurerängste", description = "{name}, ich habe vor Kurzem mit Mei gesprochen, einer Reittierhändlerin, und sie hat mich gefragt, ob man ein Pferdegeschirr herstellen könnte, mit dem Abenteurer stabiler auf ihrem Reittier sitzen.\n\nIch möchte Euch bitten, zu ihr zu gehen, um diese Idee weiter zu besprechen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid. Vielleicht können wir dieses Problem gemeinsam lösen.", sourceObjective = "Sprecht mit Mei Francis über ihre Idee zu einem Pferdegeschirr.", progress = "Was hatte Mei zu sagen?", completion = "Ich verstehe.\n\nDie Herstellung sollte nicht allzu schwierig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[40197] = { id = 40197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notwendige Materialien", description = "Um dieses Pferdegeschirr herzustellen, benötigen wir eine Menge Leder. Soll heißen: eine MENGE Leder.\n\nIch habe mir noch mal durch den Kopf gehen lassen, wie wir die Stücke alle zusammenfügen. Geht, besorgt das Leder.\n\nWenn Ihr damit zurück seid, fangen wir an, alles zu verarbeiten.", sourceObjective = "Besorgt 100 Stücke Steinbalgleder.", progress = "Das ist wahrscheinlich das größte Projekt, an dem ich je teilgenommen habe. Das ist wirklich aufregend!", completion = "Ich habe die Pläne. Habt Ihr das Leder?", sourceObjectiveStatus = "unverified-source-field" }
quests[40198] = { id = 40198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fiese Ratten!", description = "Ich sage Euch, {name}, manchmal bin ich vom Pech verfolgt.\n\nVor Kurzem ist ein Paket von Hrul eingetroffen, in dem sich Muster für einige Lederarbeiten befanden. Als ich einen Moment nicht aufgepasst habe, sind ein paar dreckige Ratten hereingekommen und damit in das Abwassersystem abgehauen!\n\nWahrscheinlich bauen sie jetzt gerade ihre Nester daraus. Bitte, {name}, könnt Ihr dort hinuntergehen und sehen, ob Ihr einige davon zurückholen könnt?", sourceObjective = "Begebt Euch auf die Schattenseite und spürt 3 Lederverarbeitungsmuster vom Hochberg auf.", progress = "Ich hoffe, sie sind nicht zu schwer beschädigt.", completion = "Ihr habt sie gut zusammengenäht. Nur schade, dass Ihr den Rattenspeichel nicht vollständig davon entfernen konntet.\n\nLasst sie uns mal gemeinsam anschauen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40199] = { id = 40199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Laufbursche für Leder", description = "Gute Neuigkeiten, {name}! Langroms Leder & Ketten hat mich vor Kurzem mit Kettenrüstungen beliefert.\n\nSie sind von höchster Qualität, und ich würde sie Euch gerne zeigen, aber scheinbar habe ich mein Brecheisen verlegt und jetzt kann ich die Kiste nicht öffnen.\n\nWenn Ihr kurz zum Laden laufen könntet, um Ersatz zu holen, dann können wir die Kiste öffnen und uns mit der Herstellungsweise beschäftigen.", sourceObjective = "Holt ein Brecheisen für Thanid.", progress = "Ich kann mich beim besten Willen nicht daran erinnern, wo ich das verdammte Ding gelassen habe!", completion = "Tja, das war doch klar, {name}. Als Ihr unterwegs wart, habe ich mein Brecheisen gefunden! Ist das nicht großartig?\n\nOh, Ihr habt auch eins aufgetrieben? Ha ha!\n\nNun, warum behaltet Ihr es nicht und schaut Euch gemeinsam mit mir diese Rüstungsteile an?", sourceObjectiveStatus = "unverified-source-field" }
quests[40200] = { id = 40200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bande der Schlacht", description = "Mögt Ihr Haustiere, {name}? Die sind so niedlich!\n\nWas ich aber wirklich gern hätte, sind mehr Sachen, mit denen ich mit ihnen spielen kann.\n\nIch bin sicher, dass Lio drüben bei der Magischen Menagerie ein paar Ideen für spaßige Spielzeuge hat. Ihr solltet Euch mal mit ihr unterhalten!", sourceObjective = "Sprecht mit Lio der Löwin beim Laden der Magischen Menagerie. Dann kehrt zu Namha zurück.", completion = "Oh, das sind gute Ideen! Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40201] = { id = 40201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielzeuge", description = "Ok, also ihre Ideen waren eine Leine, ein Bett und ein BRENNENDER REIFEN?!\n\nDas klingt ja, als wollte sie einen Zirkus oder sowas eröffnen. Trotzdem, mir gefallen diese Ideen alle, und wir sollten anfangen, sobald Ihr bereit seid.\n\nWarum arbeitet Ihr nicht an dem Bett und ich kümmere mich um die Einzelheiten für den brennenden Reifen.", sourceObjective = "Stellt einen Prototyp für ein Haustierbett her.", progress = "Achtet darauf, dass es schön kuschlig ist!", completion = "Oooh, meine Haustiere werden so putzig aussehen, wenn sie darauf sitzen. Naja, die meisten, wahrscheinlich nicht alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[40202] = { id = 40202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die abschließenden Lektionen", description = "{name}, Hrul hat um Eure Anwesenheit gebeten. Diese Botschaft liest sich so, als ob er bereit ist, seine gesamte Weisheit, die er über die Verarbeitung der Häute dieses Landes gewonnen hat, mit Euch zu teilen.\n\nIch beneide Euch, {name}. Aber ich bin auch stolz darauf, dass Ihr es geschafft habt, ihm so viel Respekt abzunötigen.\n\nGeht jetzt... und viel Glück!", sourceObjective = "Geht zu Hrul Scharfhuf auf dem Hochberg.", completion = "Das hier wird das Letzte sein, das ich Euch lehren kann.\n\nSeid Ihr bereit für die Prüfungen, die Euch erwarten?", sourceObjectiveStatus = "unverified-source-field" }
quests[40203] = { id = 40203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärke der Vergangenheit", description = "Wie Ihr wisst, ist die Haltbarkeit Eurer Rüstung nur so stark wie die Materialien, die Ihr bei der Herstellung verwendet habt.\n\nVor langer Zeit bewohnte der schwarze Drache Todesschwinge genau diesen Berg. Bei seinem Streben nach Macht zeigten sich immer mehr Risse auf seinem Körper, und er ließ Kreaturen Metallschuppen herstellen, um diese auf seine Wunden zu nähen.\n\nSeine natürlichen Schuppen fielen in seinem Hort zu Boden und sind seitdem dort. Geht, holt eine Schuppe und bringt sie mir.\n\nIhr werdet all Eure Stärke brauchen, um das zu erreichen.", sourceObjective = "Bringt eine Schuppe von Todesschwinge zu Hrul.", progress = "Wahre Stärke wird nicht dadurch bestimmt, wie viel Ihr ertragen könnt, sondern dadurch, wie lange Ihr weiter durchhaltet, wenn Euch Stärke fehlt.", completion = "Ihr enttäuscht mich nie, {name}.\n\nUnd jetzt werde ich Euch das heilige Wissen vermitteln, das einst auch an mich weitergegeben wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[40204] = { id = 40204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evolution der Vergangenheit", description = "Während wir stärkere Rüstungen herstellen, passen die Kreaturen, gegen die wir kämpfen, sich an und lernen, uns zu besiegen. Im Gegenzug erschaffen wir bessere Rüstungen und sie lernen wieder, auch diese zu überwinden.\n\nDie Basilisken der Hochebene sind Kreaturen, gegen die meine Leute seit Jahrhunderten kämpfen. Sie haben sich genauso sehr an uns angepasst wie wir uns an sie.\n\nGeht, tötet diese Basilisken und häutet sie. Kehrt dann zu mir zurück, damit ich Euch zeigen kann, wie sie sich weiterentwickelt haben.", sourceObjective = "Besorgt 5 Basiliskenbälge.", progress = "Fürchtet Euch nicht vor Veränderung, denn Veränderung ist der einzige Weg vorwärts.", completion = "Seht Ihr das, {name}? Was früher einfache, weiche Schuppen waren...\n\n\n\n...sind jetzt Tod bringende, gezackte Waffen!\n\n<Als Nächstes zeigt er auf die spitzen Schuppen am hinteren Nacken der Kreatur.\n\nIch bin sicher, dass Ihr jetzt den Sinn der Veränderung versteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40205] = { id = 40205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Respekt vor der Vergangenheit", description = "Wir zeichnen die Fehler der Vergangenheit auf, damit wir lernen, sie in der Gegenwart zu vermeiden. Dennoch wollen wir mit den Aufzeichnungen nicht nur Fehler vermeiden, sondern auch unsere Erfolge feiern.\n\nÜberall auf dem Hochberg stehen an heiligen Orten Ständer mit geprägtem Leder, die fast so aussehen wie diese hier. Darauf stehen Geschichten.\n\nGeht an diese Orte, erweist Euren Respekt und lernt ihre Lektionen.", sourceObjective = "Geht zu den vier Gerbgestellen auf dem Hochberg und erfahrt ihre Geschichten.", progress = "Ich hoffe, diese Reise wird Euch erleuchten.", completion = "Ihr seht weiser aus, {name}. Die Ahnen haben Euch offensichtlich für würdig befunden, von ihnen zu lernen...\n\n...genau wie ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[40206] = { id = 40206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beglichene Schuld", description = "Also, ich habe noch nie davon gehört, dass ein Geist einen Brief verschickt, aber ich will verflucht sein, wenn ich nicht gerade einen bekommen habe.\n\nCelea hat nach Euch gerufen, <mein Junge/meine Liebe>. Ich an Eurer Stelle würde mich ganz schnell auf den Weg machen. Einen Geist warten zu lassen, könnte Unglück bedeuten.", sourceObjective = "Geht zu Celea in Azsuna.", completion = "Danke für Euer Kommen, {name}. Ich wünsche den Rest meiner Weisheit mit Euch zu teilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40207] = { id = 40207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppen des Arkanen", description = "Meiner Erfahrung nach sind Drachenschuppen das stärkste Material, mit dem ich je die Ehre hatte zu arbeiten. Sie sind hart, widerstandsfähig und man kommt mit sehr wenig sehr lange aus.\n\nIch wünschte, ich könnte erneut damit arbeiten, {name}. In dieser Gestalt bin ich an diesen Bereich gefesselt und nicht mehr in der Lage, die Welt zu erfahren.\n\nIch habe Gerüchte gehört, dass der blaue Drachenschwarm Teile von Azsuna bevölkert. Vielleicht könntet Ihr mit ihnen sprechen und sehen, ob sie die eine oder andere Schuppe entbehren können.", sourceObjective = "Sprecht mit dem blauen Drachenschwarm und bringt eine ihrer Schuppen an Euch.", progress = "Wieder mit Drachenschuppen zu arbeiten, wäre eine große Ehre.", completion = "Ja, die sind perfekt, {name}. Es ist nur fair, dass ich diesen großen Gefallen erwidere und Euch noch mehr von meinem Wissen über Lederverarbeitung vermittle.", sourceObjectiveStatus = "unverified-source-field" }
quests[40208] = { id = 40208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Schuppen des Meeres", description = "Als wir uns das erste Mal begegneten, sprach ich von den Naga und den Rüstungen, die sie herstellen können. Doch es gibt keine großartigeren Rüstungen als die, die ihre obersten Kriegsherren tragen.\n\nEiner davon hält sich im Auge Azsharas auf. Sein Name ist Kriegsherr Parjesh und die Halsberge, die er trägt, ist legendär.\n\nBesiegt seine Truppen und bringt mir seine Rüstung. Dann lehre ich Euch noch mehr über die azsunianische Kunst der Lederverarbeitung.", sourceObjective = "Begebt Euch zum Auge Azsharas und besorgt von dort Kriegsherr Parjeshs Halsberge.", progress = "Er wird sie nicht einfach so übergeben, {name}. Ihr werdet Euch einem harten Kampf stellen müssen.", completion = "Ihr habt einen mächtigen Gegner niedergestreckt, {name}. Die Naga werden Euch zweifellos jagen.\n\nBevor sie Euch allerdings erwischen, erlaubt mir, einige Dinge mit Euch zu teilen...", sourceObjectiveStatus = "unverified-source-field" }
quests[40209] = { id = 40209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schuppen der Erde", description = "Lederrüstung bietet zwar schon einigen Schutz, aber durch die Einarbeitung von Schuppen wird sie erst richtig überragend.\n\nDie Art der verwendeten Schuppen entscheidet darüber, wie viele man benötigt, um dem Träger angemessenen Schutz zu gewähren. Und Basiliskenschuppen zählen zu den stärksten Schuppen.\n\nVoll ausgewachsene Basilisken bieten natürlich die besten Schuppen. In der Nähe von Llothien gibt es eine Basiliskenhöhle. Tötet die dort lebende Matriarchin und bringt mir ihre Schuppen.", sourceObjective = "Besorgt Matriarchinnenschuppen der Hackschwanzbasilisken.", progress = "Möglicherweise müsst Ihr Euch an ihrer Brut vorbeikämpfen, um sie zu erreichen.", completion = "Basiliskenschuppen sind dick. Sogar ein dünneres Exemplar reicht aus, um jeden Schwert- oder Speerangriff abzuwehren.\n\nDiese Stärke macht die Schuppen so wertvoll für unsere Handwerkskunst.", sourceObjectiveStatus = "unverified-source-field" }
quests[40210] = { id = 40210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sinnvoll genutzte Zeit", description = "Leider habt Ihr alles gelernt, das ich Euch lehren kann, {name}. Ich bin froh, dass wir in dieser Partnerschaft beide in der Lage waren, uns gegenseitig beim Erreichen unserer Ziele zu helfen.\n\nGeht nun und teilt Euer neu erworbenes Wissen mit Euren Verbündeten in Dalaran. Ich bin sicher, dass sie begierig darauf warten, Anteil an Eurer Ausbildung zu nehmen.", sourceObjective = "Erzählt Namha von Eurer Zeit bei den Nachtelfen in Azsuna.", completion = "<Namha lauscht mit großen Augen und gespitzten Ohren Euren Geschichten.>\n\nDas ist es, {name}. Ihr habt mich inspiriert. Ich bin schon viel zu lange in dieser schwebenden Stadt gefangen. Es ist Zeit, hinauszugehen und wieder die Welt zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40211] = { id = 40211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dämonenfleisch", description = "Etwas, das wir bisher noch nicht ausreichend erforscht haben, {name}, sind die Kreaturen von Suramar. Insbesondere die Dämonen.\n\nIch will keinesfalls gutheißen, was sie sind, aber man kann die Tatsache nicht ignorieren, dass einige dieser Kreaturen besonders widerstandsfähige Bälge besitzen.\n\nWir könnten uns an den Dämonenjägern ein Beispiel nehmen und diese Bälge zu unserem Vorteil gegen die Dämonen einsetzen. Aber zum Teufel, ich habe nicht die geringste Ahnung davon, wie man Dämonenbälge verarbeitet.\n\nVielleicht gibt es jemanden in Suramar, der helfen kann...", sourceObjective = "Sucht nach einem Lederverarbeitungsmeister in Suramar.", completion = "Und ich sag noch zu ihm: \"Die Welt steht auf Messers Schneide und wir sind die Bartstoppeln!\"\n\nUnd er sagt: \"Und wer füttert dann die Säbler?!\"\n\nMoment mal... Wer seid Ihr? Lederverarbeitung? Oh... stimmt ja, ich war ja mal ein großer Lederer...", sourceObjectiveStatus = "unverified-source-field" }
quests[40212] = { id = 40212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Am falschen Ende des Messers", description = "Da ist er! Dieser Mann, der gar nicht da ist! Er ist... Er ist...\n\nMoment mal... Nein, tut mir leid. Ich bin in letzter Zeit vollkommen durcheinander. Seit meinem Exil ist alles irgendwie etwas verworrener als normal.\n\nWenn Ihr von mir lernen wollt, bevor ich vollkommen den Verstand verliere, dann tut mir einen Gefallen und tötet diese Verräter, die sich auf die Seite der Dämonen gestellt und mich verbannt haben.", sourceObjective = "Tötet die verräterischen Lederverarbeiter Feorias, Tallian und Syana.", completion = "Grün ist gut. Grün ist gut. Grün ist gut? Niemals!\n\nOh, Ihr seid es, {name}. Also schön, Ihr braucht etwas?\n\nMoment mal, sie sind tot? Und Ihr habt sie getötet? Fantastisch!", sourceObjectiveStatus = "unverified-source-field" }
quests[40213] = { id = 40213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Haufen Hunde", description = "Ich werde ihn zum Tee einladen. Das wird ihm eine Lehre sein! Er wird die Lederpuppe sehen und sagen: \"Seit wann ist SIE hier?!\"\n\nIch meine... Tut mir leid, {name}. Ich bin irgendwie vollkommen zerstreut. Ihr wolltet etwas über die Dämonen wissen? Die mit den widerstandsfähigen Bälgen?\n\nBevor ich verbannt wurde, sah ich solche Bestien durch unsere Städte streifen. Man nennt sie Teufelshunde. Tötet sie und bringt mir ihre Kadaver.\n\nÜber die Bälge können wir anschließend sprechen.", sourceObjective = "Besorgt 5 Teufelshundkadaver.", progress = "Wir haben uns am See getroffen. Es war Frühling und sie trug Leylilien...", completion = "Hey, {name}! Kommt her und hört zu. Ihr hört das doch, oder? Na kommt schon, ich weiß, dass Ihr das hört!\n\nWas sind das für fürchterliche Dinge, die Ihr hinter Euch herzieht? Teufelshunde? Für mich?\n\nIhr habt einen merkwürdigen Geschmack, was Geschenke für Eure Freunde angeht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[40214] = { id = 40214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teuflisches Gerben", description = "Hört mal zu. Ich bin nicht sicher, wann meine verrückte Seite wieder zum Vorschein kommt, also sollten wir unsere gemeinsame Zeit so gut wie möglich nutzen.\n\nIhr wollt lernen, wie man Rüstungen herstellt, mit denen man den Dämonen die Stirn bieten kann? Folgt meinen Anweisungen und Ihr werdet eine ausgezeichnete Vorstellung von den Abläufen bekommen.", sourceObjective = "Stellt mithilfe des Gerbgestells ein Paar Armschienen für Stalriss her.", progress = "Ihr seid doch wirklich hier, oder?\n\n<Stalriss streckt eine Hand aus und kneift Euch.>", completion = "Prima, Ihr habt es geschafft, {name}. Gute Arbeit.\n\nJetzt geht, bevor ich etwas sage oder tue, das ich bereuen könnte, obwohl ich mich wahrscheinlich nicht einmal daran erinnern werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[40215] = { id = 40215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reiten leicht gemacht", description = "{name}, ich bin froh, dass Ihr hier seid, und ich muss Euch etwas gestehen: Ich habe hinter Eurem Rücken an einem geheimen Projekt gearbeitet, dem Steinbalglederzaumzeug! Jetzt müssen wir für diese hochwertige Ausrüstung nur noch das passende Reittier finden.\n\nIn den Liedern der Vrykul finden schneeweiße Urhörner mit endloser Ausdauer Erwähnung. Findet so ein Tier, legt ihm das Zaumzeug an und zähmt es.", sourceObjective = "Fangt das große Nordurhorn.", completion = "Also das ist mal ein würdiges Reittier. Hier ist das Muster für das Zaumzeug, wenn Ihr auch eins möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[40216] = { id = 40216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jägerin im Herzen", description = "Addie ist eine überragende Schreiberin, aber ich habe sie noch nie ein Gewehr halten sehen. Sie möchte unbedingt das Jagen lernen, aber hat man schon mal was von Gnomjägern gehört? \n\nIhr scheint ja gut mit solchen Amateuren auszukommen. Würde es Euch etwas ausmachen, den Gnom mit auf die Jagd zu nehmen? Von jemandem mit Euren Fähigkeiten kann sie sicher eine Menge lernen.\n\nIhr fangt am besten mit kleinerer Beute an. Wir wollen sie ja nicht gleich entmutigen.", sourceObjective = "Helft Addie, das Jagen zu lernen, indem Ihr im Kieferfelsbecken auf Beutejagd geht.", completion = "Da Ihr nicht komplett durchlöchert seid, ist Addies Zielvermögen ja offensichtlich gar nicht so schlecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[40217] = { id = 40217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befiederte Gabe", description = "Durch die Täler dieses Gebirges sind schon viele Reisende gezogen, die unseren Traditionen keine Beachtung schenkten.\n\nUnsere Anführer haben wichtigere Dinge zu tun, aber Losro und ich können die kürzliche Ankunft der Jäger im nahegelegenen Becken nicht ignorieren.\n\nSie jagen mit Feuerwaffen und anderen Gerätschaften und verweigern sich der traditionellen Jagd mit Pfeil und Bogen.\n\nWir werden nicht alle überzeugen können, aber vielleicht können wir einigen von ihnen unsere Jagdkultur näherbringen, wenn wir ihnen ein paar Pfeile schenken.", sourceObjective = "Bringt den Köcher mit Pfeilen zu Hemet Nesingwary in Nesingwarys Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Wir verwenden solche Munition schon lange nicht mehr! Aber keine Sorge, wir werden diese Pfeile schon zu nutzen wissen – zum Beispiel als Feuerholz.", sourceObjectiveStatus = "unverified-source-field" }
quests[40218] = { id = 40218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgezahlte Schuld", description = "Ich muss mich um ein paar dringende Angelegenheiten kümmern, aber gleich danach werde ich mich zur Schreckensnarbe begeben und Euch bei den Beschwörungen helfen.\n\nSagt Ritssyn, dass er sich von mir fernhalten soll. Ich werde dort sein, um meine Schuld bei Euch zu begleichen, und nicht, um mit diesem Heuchler zu sprechen, der seine Freunde zugunsten des Rates im Stich lässt.", sourceObjective = "Sprecht mit Ritssyn Flammengroll.", completion = "Kira ist Euren Worten schon vorausgeeilt. Sie ist vor wenigen Augenblicken hier angekommen und hat mich seitdem keines Blickes gewürdigt.\n\nIhr scheint ihr Vertrauen zu genießen. Das ist mir nie gelungen. Mit ihrer Hilfe sollten wir das Tor heraufbeschwören können.", sourceObjectiveStatus = "unverified-source-field" }
quests[40219] = { id = 40219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesschwinge zum Trotz", description = "An diesem Ort hat Huln Hochberg vor vielen, vielen Jahren den großen Todesschwinge herausgefordert.\n\nUnd heute werden wir die großen Momente dieses Tages durch die Augen unserer Vorfahren erneut miterleben dürfen.\n\nFür den nächsten Teil unserer Geistreise müssen wir die drei Kohlenpfannen aufsuchen, die vor langer Zeit aufgestellt wurden, damit alle, die Huln nacheifern wollen, seine großen Taten nacherleben können.", sourceObjective = "Erlebt 3 Visionen.", completion = "Und so kam Huln Hochberg zu diesem Berg, befreite die von Todesschwinge versklavten Drogbar und nahm den Hammer von Khaz'goroth in seinen Besitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[40220] = { id = 40220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorniger Tanz", description = "Die Distelblattwaldgeister sind vollkommen übergeschnappt.\n\nIch fürchte, sie werden von einigen sehr bösartigen Dorntänzern manipuliert.\n\nIch bitte Euch, <Freund/Freundin> des Waldes, findet diese verführerischen Tunichtgute und stellt den Frieden am Tümpel wieder her.", sourceObjective = "Besiegt 3 Distelblattdorntänzer im Mondschwingentümpel.", progress = "Habt Ihr Euch bereits um diese Dorntänzer gekümmert?", completion = "Das sollte diese verfluchten Dorntänzer hoffentlich das Weite suchen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40221] = { id = 40221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mondschwingen in Not", description = "Die armen Feendrachen leiden furchtbare Qualen!\n\nUnd das Schlimmste daran ist: Wenn die Distelblattgeister genug haben, fesseln sie ihre Opfer, um sie später noch weiter zu malträtieren.\n\nSo kann das nicht weitergehen.\n\nBefreit bitte alle gefangenen Mondschwingen, die Ihr finden könnt.", sourceObjective = "Rettet 8 gefangene Mondschwingen am Mondschwingentümpel.", completion = "Ich danke Euch im Namen der Mondschwingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40222] = { id = 40222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Foliant der Wichtelmutter", description = "Seht Ihr diese riesige Höhle? Dort lauert eine schreckliche, extrem mächtige Wichtelmutter.\n\nDas ist natürlich nicht die gute Nachricht. Die befindet sich in ihren stinkenden Klauen.\n\nWir hörten, sie ist eine Art dämonische Geheimnisträgerin. Sie führt dort abscheuliche Rituale für die Legion durch und hält sie in einem Buch fest.\n\nWir brauchen diese Macht! Wir brauchen dieses Buch!", sourceObjective = "Beschafft den Folianten der Dämonengeheimnisse.", progress = "Habt Ihr ihn?", completion = "Spürt Ihr die Macht, die dem Buch entströmt? Ich kann kaum erwarten, seine Geheimnisse zu ergründen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40223] = { id = 40223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 DH-Mardum - Small Treasure Chest 008" }
quests[40224] = { id = 40224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hammer in der Tiefe", description = "<Thrall hört genau zu.>\n\nIhr habt ihn gefunden! Der Schicksalshammer ist in die Bruchtiefen gefallen... doch die Legion ist uns noch immer einen Schritt voraus. Wenn wir uns beeilen, können wir dem Dämon Geth'xun folgen und den Hammer beschaffen, bevor noch mehr von diesem Reich verderbt wird.\n\nTherazane wird ein Portal öffnen, das direkt dort hinführt. Lasst uns aufbrechen!", sourceObjective = "Nutzt Therazanes Portal, um in die Bruchtiefen zu gelangen, und helft Sturmruferin Mylra und Thrall, den Schicksalshammer zu bergen.", completion = "In einer Prophezeiung der Orcs hieß es, dass ein Fremder den Schicksalshammer ergreifen und für Gerechtigkeit sorgen würde. Vielleicht... ja, vielleicht wart IHR damit gemeint.\n\nKommt, {name}. Der Irdene Ring braucht Euch. Und Azeroth braucht uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[40225] = { id = 40225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein neu geschmiedeter Ring", description = "Sprecht mit Nobundo und nehmt Euren Platz im Kreis ein, {name}. Der Irdene Ring wird sich erneut erheben, und Ihr werdet <sein Anführer/seine Anführerin> sein!\n\nZwischen diesen Steinen befindet sich das legendäre Herz von Azeroth, das wir als Operationsbasis nutzen können. Vielleicht lassen sich mit der Macht Eures Artefakts die verborgenen Kammern öffnen...", sourceObjective = "Sprecht mit Nobundo und nehmt Euren Platz als <Anführer/Anführerin> des Irdenen Rings ein.", progress = "In Allianz und Horde herrscht das Chaos. Wenn wir Azeroth retten wollen, müssen wir Schamanen unsere Kräfte bündeln!", completion = "Der Irdene Ring erhebt sich erneut, um Azeroth zu retten. Ihr werdet unser Scharfseher und wir die Werkzeuge Eurer Führung sein, {name}. Wir können unsere Welt nur retten, indem wir zusammenarbeiten.\n\nWir stehen Euch zu Diensten, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[40227] = { id = 40227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Absichten", description = "Suramar ist verloren.\n\nUnsere Anführer haben sich auf ein düsteres Geschäft eingelassen und die Legion als unsere Verbündeten akzeptiert. Wir hätten Helden und Hüter sein sollen, wie die Leute, die hier ruhen. Aber wir sind nicht mehr wie sie. Ich kann nicht mit ihnen leben.\n\nAber vom Nachtbrunnen abgeschnitten würden wir verdorren und eine verstandeslose Existenz führen. Eine gänzlich verzweifelte und würdelose Existenz, wie man selbst hier sehen kann...\n\nIch habe beide Möglichkeiten abgelehnt und bin hierhergekommen. Ich werde einen dritten Weg finden.", sourceObjective = "Sprecht mit Thaedris Federsang in Tel'anor.", progress = "Warum wollt Ihr mich davon abbringen?", completion = "Die tröstenden Worte eines Fremden... Doch sie ändern nichts an meinem Entschluss. Kommt, sonst werde ich verdorrt sein, bevor wir fertig sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[40228] = { id = 40228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausspähen", description = "Ihr habt bewiesen, dass selbst ein Gnom mit einem Gewehr umgehen kann – eine beeindruckende Leistung. Aber um Addies Fähigkeiten endgültig unter Beweis zu stellen, muss sie noch ein wahrhaft imposantes Tier erlegen.\n\nGerüchten zufolge soll ein gefräßiger Roc seine Kreise über dem Becken ziehen. Man sagt, er sei durch Harpyienmagie verflucht, aber noch hat ihn keiner aus der Nähe zu Gesicht bekommen.\n\nNehmt diese Leuchtpistole und feuert sie ab, wenn Ihr den Roc gefunden habt. Sobald wir das Signal sehen, wird unsere Jagdgesellschaft Euch zur Hilfe eilen, um diese Bestie zu erlegen.", sourceObjective = "Tötet Grimmschwinge, nachdem Ihr seine Position mittels einer Leuchtpistole angezeigt habt.", progress = "Steht da nicht einfach nur rum. Raus mit Euch ins Becken und findet diesen Vogel!", completion = "Diese Jagd werde ich so schnell nicht vergessen!\n\nAddie wird natürlich diese Abenteuergeschichte niederschreiben. Aber nicht viele werden glauben, dass eine Gnomin eine Bestie erlegt hat, die zehnmal so groß war wie sie selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[40229] = { id = 40229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schritt in die Dunkelheit", description = "Nachdem die Gefahr für mein Volk gebannt ist, möchte ich Euch meiner Sippe vorstellen.\n\nTrefft mich an der Dunkelsteingrotte. Dann werde ich Euch zeigen, wie wir leben.", sourceObjective = "Sprecht mit Navarrogg an der Dunkelsteingrotte.", completion = "Willkommen in unserem bescheidenen Zuhause. Von jetzt an könnt Ihr Euch hier frei bewegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40230] = { id = 40230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Klau-kühnes Unterfangen", description = "Klaukühn, der Anführer der Höhlenmoosmakrura, will das Höhlenmoosdorf überfallen, um sich den Nachwuchs als Mahlzeit einzuverleiben.\n\nDas dürfen wir nicht zulassen. Murky und seine Kaulquappen werden ihre Stärke beweisen und ihn vernichten!\n\nDas ist eine Mission für Murlocs.\n\nVerschmelzt Eure Gedanken mit denen von Murky in seinem Ei und zeigt ihm, wie es gemacht wird!", sourceObjective = "Verschmelzt Eure Gedanken mit denen von Murky und besiegt Klaukühn.", completion = "Ihr habt es geschafft! Murky wird ein großer Anführer der nächsten Generation Murlocs hier sein.\n\nIch bin traurig, meinen kleinen Kumpel zu verlieren, aber manchmal muss man sie eben gehen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[40231] = { id = 40231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: Count Nefarious" }
quests[40232] = { id = 40232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: King Voras" }
quests[40233] = { id = 40233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Brood Queen's Court: Overseer Brutarg" }
